insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('anatomia-dental', 1, 'mcq', 'En el sistema de nomenclatura universal (ADA), el diente número 1 corresponde a:', '["Tercer molar superior izquierdo","Incisivo central superior derecho","Tercer molar superior derecho","Primer molar inferior derecho"]', 2, NULL, NULL, NULL, NULL, NULL, 'La secuencia comienza en el cuadrante superior derecho, en el diente más posterior.', 10, 1, '{"nomenclatura universal","numeración dental"}'),
  ('anatomia-dental', 1, 'mcq', 'La superficie del diente orientada hacia la línea media del arco dentario se denomina:', '["Distal","Mesial","Vestibular","Oclusal"]', 1, NULL, NULL, NULL, NULL, NULL, 'Significa ''hacia el centro del arco''.', 10, 1, '{"superficies dentarias","terminología"}'),
  ('anatomia-dental', 1, 'mcq', '¿Cuál es el primer diente de la dentición temporal en erupcionar en la cavidad bucal?', '["Incisivo central superior","Primer molar temporal","Canino temporal","Incisivo central inferior"]', 3, NULL, NULL, NULL, NULL, NULL, 'Comienza por los dientes anteriores del maxilar inferior.', 10, 1, '{"cronología de erupción","dentición temporal"}'),
  ('anatomia-dental', 1, 'mcq', '¿Qué tejido constituye la mayor parte del volumen de la estructura del diente?', '["Esmalte","Cemento","Dentina","Pulpa"]', 2, NULL, NULL, NULL, NULL, NULL, 'Es el tejido que queda por debajo del esmalte y del cemento.', 10, 1, '{"tejidos del diente","dentina"}'),
  ('anatomia-dental', 1, 'mcq', 'En los dientes anteriores, la cámara pulpar se continúa con:', '["un solo conducto radicular","dos conductos radiculares","tres conductos radiculares","ningún conducto"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es la configuración más simple de la cavidad pulpar.', 10, 1, '{"cámara pulpar","anatomía de conductos","dientes anteriores"}'),
  ('anatomia-dental', 1, 'mcq', 'La corona anatómica de un diente es la porción:', '["que se observa en la boca","localizada por encima de la encía","cubierta por cemento","cubierta por esmalte"]', 3, NULL, NULL, NULL, NULL, NULL, 'No depende de la encía, sino del tejido que la recubre.', 10, 1, '{"corona anatómica","corona clínica"}'),
  ('anatomia-dental', 1, 'mcq', 'Los espacios en forma de triángulo o de ''V'' que se forman entre las superficies proximales de dos dientes contiguos se denominan:', '["Embrasures","Fóveas","Surcos de desarrollo","Bordes marginales"]', 0, NULL, NULL, NULL, NULL, NULL, 'Son espacios de separación entre dientes vecinos, alrededor del punto de contacto.', 10, 1, '{"embrasures","espacios interproximales"}'),
  ('anatomia-dental', 1, 'mcq', 'Respecto al incisivo central superior, el incisivo lateral superior se caracteriza por presentar:', '["corona más ancha y raíz más larga","corona más estrecha y raíz más corta","mayor número de cúspides","dos raíces"]', 1, NULL, NULL, NULL, NULL, NULL, 'Es el diente ''más pequeño'' del grupo anterior superior.', 10, 1, '{"morfología","incisivo lateral superior"}'),
  ('anatomia-dental', 2, 'mcq', 'El primer premolar inferior se caracteriza por presentar:', '["dos cúspides de igual tamaño","tres cúspides vestibulares","una única cúspide prominente","una cúspide vestibular grande y una cúspide lingual pequeña"]', 3, NULL, NULL, NULL, NULL, NULL, 'La cúspide lingual es casi vestigial.', 20, 2, '{"morfología","premolar inferior"}'),
  ('anatomia-dental', 2, 'mcq', '¿Dónde alcanza el esmalte su mayor grosor en los dientes permanentes?', '["En el tercio cervical de la corona","En las cúspides de los molares (hasta unos 2,5 mm)","En la unión amelodentinaria","En los surcos de la cara oclusal"]', 1, NULL, NULL, NULL, NULL, NULL, 'Su grosor está relacionado con el desgaste funcional.', 20, 2, '{"esmalte","histología"}'),
  ('anatomia-dental', 2, 'mcq', 'El cemento celular se encuentra principalmente:', '["en la corona del diente","en la superficie oclusal","en el tercio apical de la raíz","en el tercio cervical de la raíz"]', 2, NULL, NULL, NULL, NULL, NULL, 'Se asocia con el crecimiento radicular en el extremo apical.', 20, 2, '{"cemento","histología","anatomía radicular"}'),
  ('anatomia-dental', 2, 'mcq', 'En los dientes permanentes jóvenes, los cuernos pulpares tienden a ser:', '["altos y cercanos a la superficie oclusal","ausentes","cortos y alejados de la superficie","iguales a los del adulto"]', 0, NULL, NULL, NULL, NULL, NULL, 'Riesgo de exposición durante la preparación de cavidades.', 20, 2, '{"cámara pulpar","cuernos pulpares","cavidades"}'),
  ('anatomia-dental', 2, 'mcq', 'El contorno oclusal de la corona del primer molar inferior tiene forma aproximadamente:', '["circular","triangular con el vértice hacia distal","romboide","de pera"]', 2, NULL, NULL, NULL, NULL, NULL, 'Es un cuadrilátero que se aprecia al mirar la cara oclusal.', 20, 2, '{"morfología","primer molar inferior","cúspides"}'),
  ('anatomia-dental', 2, 'mcq', 'El segundo molar superior se diferencia del primer molar superior porque:', '["siempre presenta cinco cúspides","suele presentar la cúspide distopalatina menor o ausente","presenta una raíz única","carece de cámara pulpar"]', 1, NULL, NULL, NULL, NULL, NULL, 'Compara el número de cúspides en el lado palatino.', 20, 2, '{"morfología","segundo molar superior"}'),
  ('anatomia-dental', 3, 'mcq', 'En endodoncia, la raíz mesiovestibular del primer molar superior es relevante porque:', '["siempre tiene un único conducto","nunca presenta conductos accesorios","su conducto es siempre de sección circular","frecuentemente presenta dos conductos (MV1 y MV2)"]', 3, NULL, NULL, NULL, NULL, NULL, 'Busca el ''segundo conducto'' de esta raíz.', 30, 3, '{"endodoncia","primer molar superior","conducto mesiovestibular"}'),
  ('anatomia-dental', 3, 'mcq', 'El dens invaginatus (diente en diente) es una variación anatómica que consiste en:', '["una invaginación de esmalte hacia el interior de la corona, con frecuencia en la fosa palatina de los incisivos laterales superiores","una cámara pulpar alargada con la furca desplazada hacia apical","la unión de dos gérmenes dentarios por el cemento","una curvatura anormal del eje de la raíz"]', 0, NULL, NULL, NULL, NULL, NULL, 'Compromete con frecuencia a los incisivos laterales superiores.', 30, 3, '{"variaciones anatómicas","dens invaginatus","endodoncia"}'),
  ('anatomia-dental', 3, 'mcq', 'El taurodontismo es una anomalía dental caracterizada por:', '["la ausencia congénita de un diente","una cámara pulpar alargada en sentido oclusoapical, con raíces cortas","la invaginación del esmalte","la fusión de la corona con el hueso alveolar"]', 1, NULL, NULL, NULL, NULL, NULL, 'Piensa en una cámara pulpar ''alargada''.', 30, 3, '{"variaciones anatómicas","taurodontismo","cámara pulpar"}'),
  ('anatomia-dental', 3, 'mcq', 'El foramen mentoniano se localiza con mayor frecuencia:', '["a nivel del segundo premolar inferior (o entre ambos premolares)","por delante del canino inferior","a nivel del primer molar inferior","en la zona del tercer molar inferior"]', 0, NULL, NULL, NULL, NULL, NULL, 'Busca en la zona de los premolares inferiores.', 30, 3, '{"anatomía aplicada","cirugía","foramen mentoniano"}'),
  ('anatomia-dental', 3, 'mcq', 'El conducto radicular en forma de ''C'' se observa con mayor frecuencia en:', '["el incisivo central superior","el canino superior","el segundo molar inferior con raíces fusionadas por lingual","el primer premolar superior"]', 2, NULL, NULL, NULL, NULL, NULL, 'Se asocia a la fusión radicular en molares inferiores.', 30, 3, '{"endodoncia","conducto en C","segundo molar inferior"}'),
  ('anatomia-dental', 2, 'mcq', '¿Por qué los ápices de los molares superiores tienen una relación clínica importante con el seno maxilar?', '["El piso del seno maxilar puede estar muy cercano o en contacto con sus ápices","El seno maxilar recubre las raíces de los dientes anteriores","El seno maxilar se encuentra por debajo de la mandíbula","No existe relación entre ambos"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en las complicaciones de una infección o exodoncia de un molar superior.', 20, 2, '{"anatomía aplicada","seno maxilar","molares superiores"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('anatomia-dental', 1, 'true_false', 'Los dientes anteriores (incisivos y caninos) presentan típicamente una sola raíz.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 10, 1, '{"morfología","raíces","dientes anteriores"}'),
  ('anatomia-dental', 1, 'true_false', 'La cara oclusal está presente únicamente en los dientes posteriores.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 10, 1, '{"morfología","superficies dentarias"}'),
  ('anatomia-dental', 2, 'true_false', 'La dentina es un tejido más duro que el esmalte.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, NULL, 20, 2, '{"esmalte","dentina","histología"}'),
  ('anatomia-dental', 2, 'true_false', 'El odontoblasto es la célula que se localiza en la periferia de la pulpa, en contacto con la dentina.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 20, 2, '{"pulpa","odontoblastos","histología"}'),
  ('anatomia-dental', 2, 'true_false', 'La erupción pasiva del diente consiste en el desplazamiento de la corona hacia el plano oclusal.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, 'Relaciona ''pasiva'' con la encía, no con el diente.', 20, 2, '{"erupción dental","erupción pasiva","encía"}'),
  ('anatomia-dental', 3, 'true_false', 'La reabsorción radicular fisiológica ocurre de manera habitual en la dentición permanente.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"reabsorción radicular","dentición temporal","patología"}'),
  ('anatomia-dental', 3, 'true_false', 'El nervio alveolar inferior discurre por el interior del conducto mandibular, por debajo de los ápices de los dientes inferiores.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"anatomía aplicada","conducto mandibular","nervio alveolar inferior"}'),
  ('anatomia-dental', 1, 'fill_blank', 'El esmalte está compuesto principalmente por cristales de ____.', '["colágeno tipo I","hidroxiapatita","queratina","glucosaminoglicanos"]', 1, NULL, NULL, NULL, NULL, NULL, NULL, 10, 1, '{"esmalte","composición química"}'),
  ('anatomia-dental', 1, 'fill_blank', 'La superficie del diente orientada hacia los labios o las mejillas se denomina cara ____.', '["vestibular","mesial","distal","oclusal"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 10, 1, '{"superficies dentarias","terminología"}'),
  ('anatomia-dental', 2, 'fill_blank', 'La frontera entre el esmalte y la dentina se conoce como unión ____.', '["amelocementaria","amelodentinaria","dentinocementaria","amelopulpar"]', 1, NULL, NULL, NULL, NULL, NULL, NULL, 20, 2, '{"esmalte","dentina","unión amelodentinaria"}'),
  ('anatomia-dental', 2, 'fill_blank', 'La dentina que rodea cada túbulo dentinario y es más mineralizada se denomina dentina ____.', '["intertubular","primaria","peritubular","esclerótica"]', 2, NULL, NULL, NULL, NULL, NULL, NULL, 20, 2, '{"dentina","dentina peritubular","histología"}'),
  ('anatomia-dental', 2, 'fill_blank', 'La capa de dentina sin mineralizar que se encuentra entre la pulpa y la dentina madura se denomina ____.', '["esclerótica","predentina","peritubular","circumpulpar"]', 1, NULL, NULL, NULL, NULL, NULL, NULL, 20, 2, '{"dentina","predentina","histología"}'),
  ('anatomia-dental', 3, 'fill_blank', 'La terminación del conducto radicular en múltiples ramas y forámenes cerca del ápice se denomina ____.', '["istmo","conducto lateral","delta apical","conducto colateral"]', 2, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"anatomía de conductos","delta apical","endodoncia"}'),
  ('anatomia-dental', 3, 'fill_blank', 'La anomalía en la que dos gérmenes dentarios se unen y forman una pieza con dos coronas se denomina ____.', '["fusión","gemación","concrescencia","dilaceración"]', 0, NULL, NULL, NULL, NULL, NULL, 'No confundir con gemación, que parte de un solo germen.', 30, 3, '{"anomalías del desarrollo","fusión","morfología"}'),
  ('anatomia-dental', 1, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles de los siguientes grupos dentarios forman parte de la dentición anterior?', '["Incisivos","Caninos","Premolares","Molares"]', NULL, '{0,1}', NULL, NULL, NULL, NULL, NULL, 10, 1, '{"grupos dentarios","dentición anterior"}'),
  ('anatomia-dental', 1, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles de las siguientes son las caras proximales (de contacto) del diente?', '["Vestibular","Mesial","Palatina","Distal"]', NULL, '{1,3}', NULL, NULL, NULL, NULL, NULL, 10, 1, '{"superficies dentarias","terminología"}'),
  ('anatomia-dental', 2, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles de las siguientes son funciones de la pulpa dental?', '["Mineralización del esmalte","Formación de dentina","Sensibilidad (nocicepción)","Nutrición del tejido dentinario"]', NULL, '{1,2,3}', NULL, NULL, NULL, NULL, NULL, 20, 2, '{"pulpa dental","funciones","histología"}'),
  ('anatomia-dental', 2, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles de las siguientes son características del cemento radicular?', '["Es más duro que el esmalte","Es un tejido avascular","Contiene odontoblastos en su interior","Es más blando que la dentina"]', NULL, '{1,3}', NULL, NULL, NULL, NULL, NULL, 20, 2, '{"cemento","histología","raíz"}'),
  ('anatomia-dental', 3, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles de los siguientes hallazgos anatómicos pueden complicar el tratamiento de conductos?', '["Curvaturas radiculares pronunciadas","Conductos accesorios","Coronas sin caries ni restauraciones","Istmos entre conductos"]', NULL, '{0,1,3}', NULL, NULL, NULL, NULL, NULL, 30, 3, '{"endodoncia","anatomía de conductos","complejidad"}'),
  ('anatomia-dental', 3, 'multi_select', 'Selecciona todas las que apliquen. ¿Qué células participan en la formación de los tejidos duros del diente?', '["Ameloblastos (esmalte)","Osteoclastos (reabsorción ósea)","Odontoblastos (dentina)","Cementoblastos (cemento)"]', NULL, '{0,2,3}', NULL, NULL, NULL, NULL, NULL, 30, 3, '{"histología","odontogénesis","células"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('anatomia-dental', 1, 'match', 'Empareja cada grupo dentario con su función principal.', NULL, NULL, NULL, '[{"left":"Incisivos","right":"Corte de los alimentos"},{"left":"Caninos","right":"Desgarro o prensión"},{"left":"Premolares","right":"Trituración"},{"left":"Molares","right":"Molienda"}]', NULL, NULL, NULL, NULL, 15, 1, '{"grupos dentarios","función"}'),
  ('anatomia-dental', 2, 'match', 'Empareja cada porción de la cavidad pulpar con su descripción.', NULL, NULL, NULL, '[{"left":"Cámara pulpar","right":"Porción de la cavidad pulpar situada en la corona"},{"left":"Piso de la cámara pulpar","right":"Pared cervical donde se abren los orificios de los conductos"},{"left":"Conducto radicular","right":"Porción de la cavidad pulpar situada en la raíz"},{"left":"Conducto lateral","right":"Rama del conducto que desemboca en el periodonto lateral"}]', NULL, NULL, NULL, NULL, 25, 2, '{"cavidad pulpar","anatomía de conductos"}'),
  ('anatomia-dental', 3, 'match', 'Empareja cada anomalía del desarrollo dental con su característica.', NULL, NULL, NULL, '[{"left":"Dens evaginatus","right":"Proyección de esmalte sobre el surco oclusal de los premolares"},{"left":"Dilaceración","right":"Curvatura anormal del eje de la corona o de la raíz"},{"left":"Concrescencia","right":"Unión de dos dientes a través del cemento"},{"left":"Gemación","right":"División incompleta de un germen que forma una sola raíz"}]', NULL, NULL, NULL, NULL, 35, 3, '{"anomalías del desarrollo","variaciones anatómicas"}'),
  ('anatomia-dental', 3, 'match', 'Empareja cada tejido dentario con su origen embriológico.', NULL, NULL, NULL, '[{"left":"Esmalte","right":"Órgano del esmalte (ectodermo)"},{"left":"Dentina y pulpa","right":"Papila dental (ectomesénquima)"},{"left":"Cemento, ligamento periodontal y hueso alveolar","right":"Saco o folículo dental (ectomesénquima)"}]', NULL, NULL, NULL, NULL, 35, 3, '{"embriología","histología","origen de tejidos"}'),
  ('anatomia-dental', 1, 'order', 'Ordena las capas del diente en la corona, desde la superficie externa hacia la pulpa.', NULL, NULL, NULL, NULL, '[{"text":"Esmalte","position":1},{"text":"Dentina","position":2},{"text":"Pulpa","position":3}]', NULL, NULL, NULL, 15, 1, '{"estructura del diente","corona"}'),
  ('anatomia-dental', 2, 'order', 'Ordena cronológicamente las fases de la erupción dental.', NULL, NULL, NULL, NULL, '[{"text":"Fase preeruptiva","position":1},{"text":"Fase prefuncional (erupción activa)","position":2},{"text":"Fase funcional (erupción compensatoria)","position":3}]', NULL, NULL, NULL, 25, 2, '{"erupción dental","cronología"}'),
  ('anatomia-dental', 3, 'order', 'Ordena los pasos para localizar y tratar el sistema de conductos de un molar inferior en el acceso endodóntico.', NULL, NULL, NULL, NULL, '[{"text":"Realizar la apertura coronaria","position":1},{"text":"Localizar los orificios de los conductos","position":2},{"text":"Identificar el istmo entre los conductos mesiales","position":3},{"text":"Comprobar la permeabilidad con una lima fina","position":4}]', NULL, NULL, NULL, 35, 3, '{"endodoncia","molar inferior","procedimiento"}'),
  ('anatomia-dental', 3, 'case', 'Según el caso, ¿qué tejidos del diente están comprometidos por la fractura?', NULL, NULL, NULL, NULL, NULL, 'an-case-1', 'Un paciente de 19 años sufre un traumatismo y acude a consulta. En el incisivo central superior derecho se observa una fractura de la corona con exposición de dentina, sin exposición pulpar visible. La radiografía muestra la cámara pulpar de tamaño normal, ápices completamente formados y sin lesión periapical. El paciente refiere sensibilidad al frío.', NULL, 35, 3, '{"trauma dental","tejidos del diente","fractura coronaria"}'),
  ('anatomia-dental', 3, 'case', 'La sensibilidad al frío que refiere el paciente se explica principalmente por la estimulación de:', NULL, NULL, NULL, NULL, NULL, 'an-case-1', 'Un paciente de 19 años sufre un traumatismo y acude a consulta. En el incisivo central superior derecho se observa una fractura de la corona con exposición de dentina, sin exposición pulpar visible. La radiografía muestra la cámara pulpar de tamaño normal, ápices completamente formados y sin lesión periapical. El paciente refiere sensibilidad al frío.', NULL, 35, 3, '{"sensibilidad dentinaria","túbulos dentinarios","odontoblastos"}'),
  ('anatomia-dental', 3, 'case', 'Si en el seguimiento el diente desarrolla necrosis pulpar y se indica tratamiento de conducto, ¿qué característica anatómica de este diente facilita la instrumentación?', NULL, NULL, NULL, NULL, NULL, 'an-case-1', 'Un paciente de 19 años sufre un traumatismo y acude a consulta. En el incisivo central superior derecho se observa una fractura de la corona con exposición de dentina, sin exposición pulpar visible. La radiografía muestra la cámara pulpar de tamaño normal, ápices completamente formados y sin lesión periapical. El paciente refiere sensibilidad al frío.', NULL, 35, 3, '{"endodoncia","incisivo central superior","anatomía de conductos"}'),
  ('endodoncia', 1, 'mcq', 'En el primer molar superior, ¿cuál es el número de conductos que suele contener la raíz palatina?', '["1 conducto","2 conductos","3 conductos","4 conductos"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en la raíz más recta y de mayor volumen de ese molar.', 10, 1, '{"anatomia","numero-de-conductos","molar-superior"}'),
  ('endodoncia', 1, 'mcq', 'La prueba de percusión evalúa principalmente el estado de:', '["la pulpa","el ligamento periodontal periapical","el esmalte","la dentina coronaria"]', 1, NULL, NULL, NULL, NULL, NULL, '¿Qué tejido sostiene al diente en el alvéolo y se tensa al golpearlo?', 10, 1, '{"diagnostico","percusión","pruebas-diagnosticas"}'),
  ('endodoncia', 1, 'mcq', '¿Qué respuesta se espera ante la prueba de frío en un diente con necrosis pulpar total?', '["Ausencia de respuesta","Dolor agudo breve","Dolor prolongado","Dolor pulsátil"]', 0, NULL, NULL, NULL, NULL, NULL, 'Recuerda qué le ocurre a la pulpa cuando pierde completamente su vitalidad.', 10, 1, '{"diagnostico","necrosis","pruebas-termicas"}'),
  ('endodoncia', 1, 'mcq', '¿Con qué instrumento se realiza habitualmente la prueba de percusión?', '["Con el mango del espejo dental o un instrumento metálico","Con una lima endodóntica","Con un explorador de punta afilada","Con el condensador de gutapercha"]', 0, NULL, NULL, NULL, NULL, NULL, 'El instrumento debe golpear con una superficie roma, no cortante.', 10, 1, '{"diagnostico","percusión","pruebas-diagnosticas"}'),
  ('endodoncia', 1, 'mcq', '¿Cuál de los siguientes es un diagnóstico pulpar?', '["Pulpitis reversible","Absceso periapical","Celulitis","Quiste radicular"]', 0, NULL, NULL, NULL, NULL, NULL, 'Busca la opción que describe el estado de la pulpa, no de los tejidos que la rodean.', 10, 1, '{"diagnostico","clasificacion","diagnostico-pulpar"}'),
  ('endodoncia', 1, 'mcq', 'La palpación en la exploración endodóntica busca detectar:', '["Edema, sensibilidad o fluctuación en los tejidos alrededor del ápice","El número de conductos","La longitud de trabajo","La vitalidad pulpar"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es la prueba manual que presiona la encía y la mucosa sobre la zona del ápice.', 10, 1, '{"diagnostico","palpación","pruebas-diagnosticas"}'),
  ('endodoncia', 1, 'mcq', 'Una radiolucidez periapical detectada en la radiografía, sin dolor ni sensibilidad clínica, corresponde a:', '["Periodontitis apical asintomática","Pulpitis irreversible","Celulitis","Gingivitis"]', 0, NULL, NULL, NULL, NULL, NULL, 'La ausencia de síntomas es el dato decisivo del enunciado.', 10, 1, '{"diagnostico","diagnostico-periapical","periodontitis-asintomatica"}'),
  ('endodoncia', 1, 'mcq', 'La transiluminación con fibra óptica es una ayuda diagnóstica útil para detectar:', '["Fracturas coronales no visibles a simple vista","El número de conductos","La longitud del conducto","La vitalidad pulpar"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué defecto dental se ve mejor cuando la luz no atraviesa limpiamente el diente?', 10, 1, '{"diagnostico","transiluminacion","fracturas"}'),
  ('endodoncia', 1, 'true_false', 'La percusión evalúa el estado del ligamento periodontal, no el de la pulpa.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, 'Fíjate en qué tejido recibe directamente el impacto del golpe.', 10, 1, '{"diagnostico","percusión"}'),
  ('endodoncia', 1, 'true_false', 'Un diente con necrosis pulpar nunca responde a la percusión.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, 'La percusión explora el periodonto; ¿puede estar inflamado aunque la pulpa esté muerta?', 10, 1, '{"diagnostico","necrosis","percusión"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('endodoncia', 1, 'true_false', 'La respuesta positiva a la percusión es exclusiva de la patología pulpar.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, 'Relaciona la percusión con el tejido que rodea la raíz, no con la pulpa.', 10, 1, '{"diagnostico","percusión"}'),
  ('endodoncia', 1, 'fill_blank', 'Las entradas de los conductos radiculares se localizan sobre el suelo de la cámara ____.', '["pulpar","gingival","ósea","dentinaria"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es la cámara interna de la corona donde se aloja la pulpa.', 10, 1, '{"anatomia","camara-pulpar"}'),
  ('endodoncia', 1, 'fill_blank', 'El diagnóstico pulpar que describe una pulpa sin síntomas y con respuesta normal a las pruebas de sensibilidad se denomina pulpa ____.', '["normal","necrótica","inflamada","calcificada"]', 0, NULL, NULL, NULL, NULL, NULL, 'Busca el término que se usa cuando no hay ninguna alteración pulpar.', 10, 1, '{"diagnostico","pulpa-normal","diagnostico-pulpar"}'),
  ('endodoncia', 1, 'multi_select', 'Selecciona todas las que apliquen. ¿Qué pruebas forman parte de la valoración diagnóstica básica en endodoncia?', '["prueba de frío","prueba de percusión","radiografía periapical","prueba de alergia","espectrofotometría"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Son las pruebas clínicas y radiográficas que se aplican a todo paciente endodóntico.', 10, 1, '{"diagnostico","pruebas-diagnosticas"}'),
  ('endodoncia', 1, 'multi_select', 'Selecciona todas las que apliquen. ¿Qué estructuras forman parte del sistema de conductos radiculares?', '["cámara pulpar","conducto principal","conductos accesorios o laterales","ligamento periodontal","esmalte"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Son las cavidades internas por donde discurre la pulpa.', 10, 1, '{"anatomia","sistema-de-conductos"}'),
  ('endodoncia', 1, 'match', 'Empareja cada diente con su número de conductos más frecuente.', NULL, NULL, NULL, '[{"left":"Incisivo central superior","right":"1 conducto"},{"left":"Canino superior","right":"1 conducto"},{"left":"Primer premolar superior","right":"2 conductos"},{"left":"Primer molar superior (raíz mesio-vestibular)","right":"2 conductos"}]', NULL, NULL, NULL, NULL, 15, 1, '{"anatomia","numero-de-conductos"}'),
  ('endodoncia', 2, 'mcq', '¿Cuál es el objetivo principal del aislamiento absoluto en endodoncia?', '["Mantener un campo libre de saliva y microorganismos","Mejorar la estética del paciente","Evitar el uso de anestesia","Reducir el tiempo de tratamiento"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en el riesgo principal que corre el conducto durante el tratamiento.', 20, 2, '{"aislamiento-absoluto","dique-de-goma"}'),
  ('endodoncia', 2, 'mcq', 'La filosofía de acceso en la apertura cameral endodóntica busca lograr un acceso:', '["En línea recta hacia la entrada de los conductos","Mínimo, conservando toda la dentina","Dirigido solo a la caries","En ángulo agudo hacia las paredes"]', 0, NULL, NULL, NULL, NULL, NULL, 'Busca el concepto que facilita que los instrumentos lleguen sin doblarse.', 20, 2, '{"apertura-cameral","acceso-endodontico"}'),
  ('endodoncia', 2, 'mcq', '¿Cuál de los siguientes es un sistema de instrumentación rotatoria?', '["ProTaper","Lima tipo K","Lima tipo H","Espaciador digital"]', 0, NULL, NULL, NULL, NULL, NULL, 'Identifica el nombre comercial que corresponde a un sistema de fresado con motor.', 20, 2, '{"instrumentacion","sistemas-rotatorios"}'),
  ('endodoncia', 2, 'mcq', 'El movimiento recíproco de los instrumentos endodónticos consiste en:', '["Rotar en ambos sentidos con mayor amplitud de giro en un sentido","Rotar de forma continua en 360 grados","Un movimiento de vaivén sin rotación","Girar solo en el sentido horario"]', 0, NULL, NULL, NULL, NULL, NULL, 'El nombre ''recíproco'' indica que el giro va y vuelve, no es continuo.', 20, 2, '{"instrumentacion","movimiento-reciproco"}'),
  ('endodoncia', 2, 'mcq', 'En la técnica de condensación vertical con calor, la gutapercha se:', '["Ablanda con calor y se compacta en sentido vertical","Introduce en frío y se condensa lateralmente","Aplica solo en la cámara pulpar","Compacta sin previo calentamiento"]', 0, NULL, NULL, NULL, NULL, NULL, 'El nombre de la técnica indica tanto el uso del calor como la dirección de compactación.', 20, 2, '{"obturacion","condensacion-vertical","calor"}'),
  ('endodoncia', 2, 'mcq', '¿Cuál es la función principal del sellador endodóntico en la obturación?', '["Rellenar las irregularidades y sellar entre la gutapercha y las paredes del conducto","Sustituir por completo la gutapercha","Proporcionar resistencia a la masticación","Blanquear las paredes dentinarias"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en el papel del ''cemento'' entre los materiales de obturación y la dentina.', 20, 2, '{"obturacion","selladores"}'),
  ('endodoncia', 2, 'true_false', 'En la instrumentación rotatoria es recomendable realizar movimientos de picoteo (pecking) y salir con frecuencia del conducto.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en cómo evitar que un instrumento giratorio se ''atornille'' en el conducto.', 20, 2, '{"instrumentacion","rotatoria","tecnicas"}'),
  ('endodoncia', 2, 'true_false', 'El sellador endodóntico debe reabsorberse por completo después de la obturación para lograr un sellado adecuado.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, 'Un material que desaparece con el tiempo, ¿mantiene el sellado o lo pierde?', 20, 2, '{"obturacion","selladores"}'),
  ('endodoncia', 2, 'fill_blank', 'La activación del irrigante dentro del conducto puede lograrse con puntas de activación ____.', '["manual","ultrasónica","giratoria","química"]', 1, NULL, NULL, NULL, NULL, NULL, 'Se trata de la energía vibratoria de alta frecuencia aplicada al irrigante.', 20, 2, '{"irrigacion","activacion-ultrasonica"}'),
  ('endodoncia', 2, 'fill_blank', 'Antes de obturar, el conducto debe secarse por completo con puntas de ____.', '["papel","algodón","gasa","plata"]', 0, NULL, NULL, NULL, NULL, NULL, 'Son conos absorbentes de celulosa de diámetro estandarizado.', 20, 2, '{"obturacion","secado","puntas-de-papel"}'),
  ('endodoncia', 2, 'fill_blank', 'En la técnica de instrumentación crown-down, la preparación avanza desde la porción ____ hacia el ápice.', '["coronaria","apical","media","cervical"]', 0, NULL, NULL, NULL, NULL, NULL, 'Traduce el nombre inglés ''crown-down'' al español.', 20, 2, '{"instrumentacion","tecnica-crown-down"}'),
  ('endodoncia', 2, 'multi_select', 'Selecciona todas las que apliquen. ¿Qué elementos forman parte del aislamiento absoluto?', '["dique de goma","arco o portadique","grapas (clamps)","brocha de polimerización","fresas de carburo"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Son las tres piezas que se montan juntas para colocar el dique.', 20, 2, '{"aislamiento-absoluto"}'),
  ('endodoncia', 2, 'multi_select', 'Selecciona todas las que apliquen. ¿Qué ventajas ofrece la instrumentación rotatoria de níquel-titanio frente a la manual?', '["mayor rapidez de preparación","menor transporte del conducto en curvaturas","elimina la necesidad de irrigación","permite omitir la medicación intraconducto","permite usar siempre el mismo diámetro apical"]', NULL, '{0,1}', NULL, NULL, NULL, NULL, 'Son las dos ventajas relacionadas con la velocidad y la flexibilidad.', 20, 2, '{"instrumentacion","rotatoria","ventajas"}'),
  ('endodoncia', 2, 'match', 'Empareja cada instrumento manual con su característica de uso.', NULL, NULL, NULL, '[{"left":"Lima K","right":"Se usa con movimientos de giro y tracción"},{"left":"Lima H","right":"Corta principalmente al retirarla (tracción)"},{"left":"Broca Gates-Glidden","right":"Amplía la porción coronaria del conducto"},{"left":"Explorador DG-16","right":"Localiza las entradas de los conductos"}]', NULL, NULL, NULL, NULL, 25, 2, '{"instrumentacion","instrumentos-manuales"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('endodoncia', 2, 'match', 'Empareja cada material o instrumento de obturación con su función.', NULL, NULL, NULL, '[{"left":"Gutapercha","right":"Núcleo principal de la obturación"},{"left":"Sellador","right":"Rellena los espacios entre gutapercha y paredes"},{"left":"Punta de papel","right":"Secado del conducto previo a la obturación"},{"left":"Condensador de calor","right":"Compactación vertical de la gutapercha"}]', NULL, NULL, NULL, NULL, 25, 2, '{"obturacion","materiales-de-obturacion"}'),
  ('endodoncia', 2, 'order', 'Ordena los pasos de la preparación del acceso endodóntico (apertura cameral).', NULL, NULL, NULL, NULL, '[{"text":"Aislar el diente con dique de goma","position":1},{"text":"Eliminar caries y restauraciones existentes","position":2},{"text":"Realizar la apertura cameral con la fresa de acceso","position":3},{"text":"Localizar y refinar las entradas de los conductos","position":4}]', NULL, NULL, NULL, 25, 2, '{"apertura-cameral","procedimiento"}'),
  ('endodoncia', 2, 'order', 'Ordena los pasos de la obturación con condensación vertical con calor.', NULL, NULL, NULL, NULL, '[{"text":"Secar el conducto con puntas de papel","position":1},{"text":"Aplicar el sellador en las paredes del conducto","position":2},{"text":"Introducir el cono maestro de gutapercha","position":3},{"text":"Condensar con calor y compactar en vertical","position":4},{"text":"Retirar el exceso coronal de gutapercha","position":5}]', NULL, NULL, NULL, 25, 2, '{"obturacion","condensacion-vertical"}'),
  ('endodoncia', 3, 'mcq', 'En un retratamiento endodóntico, el primer paso para eliminar el material de obturación antiguo es:', '["Lograr el acceso y remover la gutapercha con instrumentos calientes, solventes o ultrasonido","Obturar directamente sobre el material antiguo","Reinstrumentar sin tocar la obturación previa","Solo irrigar con agua destilada"]', 0, NULL, NULL, NULL, NULL, NULL, 'Para tratar el conducto de nuevo, primero hay que vaciarlo del material anterior.', 30, 3, '{"retratamiento","remocion-de-gutapercha"}'),
  ('endodoncia', 3, 'mcq', 'Ante una celulitis facial de origen dental, el manejo inmediato incluye:', '["Solo analgésicos y reposo","Drenaje y control del foco de infección, con antibióticos según el compromiso sistémico","Realizar un blanqueamiento dental","Extraer todos los dientes del sector"]', 1, NULL, NULL, NULL, NULL, NULL, 'Una infección difusa necesita eliminar su causa y dar salida a la colección, no solo calmar el dolor.', 30, 3, '{"urgencias","celulitis","infeccion"}'),
  ('endodoncia', 3, 'mcq', 'La dificultad para lograr anestesia profunda en un diente con pulpitis irreversible se debe principalmente a:', '["La edad avanzada del paciente","La longitud excesiva de la raíz","La inflamación que baja el pH tisular y altera la difusión del anestésico","El uso previo de antibióticos"]', 2, NULL, NULL, NULL, NULL, NULL, 'Piensa en el ambiente químico del tejido inflamado y cómo afecta al anestésico.', 30, 3, '{"anestesia","pulpitis-irreversible","manejo-del-dolor"}'),
  ('endodoncia', 3, 'mcq', 'En una lesión endo-periodontal combinada de origen principalmente endodóntico, la conducta inicial es:', '["Tratar el origen endodóntico y reevaluar la respuesta periodontal","Tratar solo el periodonto","Extraer el diente de inmediato","Aplicar únicamente antimicrobianos tópicos"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué factor causal conviene eliminar primero en una lesión combinada?', 30, 3, '{"lesion-endo-periodontal","plan-de-tratamiento"}'),
  ('endodoncia', 3, 'mcq', '¿Cuál de los siguientes factores aumenta el riesgo de fractura vertical de la raíz durante la endodoncia?', '["La irrigación con suero fisiológico","El uso de puntas de papel para el secado","El sellador de resina","La remoción excesiva de dentina durante la preparación"]', 3, NULL, NULL, NULL, NULL, NULL, 'Identifica el error de procedimiento que más adelgaza las paredes de la raíz.', 30, 3, '{"errores-de-procedimiento","fractura-radicular","preparacion"}'),
  ('endodoncia', 3, 'mcq', 'La anestesia selectiva (bloqueo del diente o cuadrante sospechoso) se utiliza en el diagnóstico para:', '["Confirmar la causa del dolor al observar su desaparición","Determinar el número de conductos","Medir la longitud de trabajo","Evaluar la movilidad dental"]', 0, NULL, NULL, NULL, NULL, NULL, 'Su nombre indica que anestesia solo una zona para probar si allí está el origen del dolor.', 30, 3, '{"diagnostico","anestesia-selectiva","dolor-orofacial"}'),
  ('endodoncia', 3, 'true_false', 'En una celulitis facial con signos de compromiso sistémico (fiebre, malestar general), el paciente puede requerir hospitalización y antibióticos parenterales.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, 'Cuando la infección afecta al estado general, el manejo deja de ser solo ambulatorio.', 30, 3, '{"urgencias","celulitis","manejo-sistemico"}'),
  ('endodoncia', 3, 'true_false', 'En la urgencia por dolor agudo de origen pulpar, el manejo correcto consiste solo en analgésicos y observación.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, 'La presión dentro de la cámara pulpar es la que genera el dolor; ¿qué debe hacerse con ella?', 30, 3, '{"urgencias","apertura-cameral","dolor-agudo"}'),
  ('endodoncia', 3, 'fill_blank', 'Para ablandar y retirar la gutapercha durante el retratamiento se pueden emplear solventes como el ____.', '["cloroformo","eucaliptol","xilol","alcohol etílico"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es el disolvente orgánico de referencia para ablandar la gutapercha.', 30, 3, '{"retratamiento","solventes","gutapercha"}'),
  ('endodoncia', 3, 'fill_blank', 'La evolución de una lesión periapical se valora comparando radiografías ____.', '["seriadas","aisladas","panorámicas","laterales"]', 0, NULL, NULL, NULL, NULL, NULL, 'Se trata de tomar la radiografía en fechas sucesivas para comparar la lesión.', 30, 3, '{"diagnostico","radiografia","retratamiento"}'),
  ('endodoncia', 3, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles son indicaciones de retratamiento endodóntico?', '["obturación deficiente con patología periapical","lesión periapical que no cicatriza","dolor persistente de origen pulpar o periapical","endodoncia correcta en diente sano","blanqueamiento interno reciente"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Elige las situaciones en las que hay un fracaso o una insuficiencia del tratamiento previo.', 30, 3, '{"retratamiento","indicaciones"}'),
  ('endodoncia', 3, 'multi_select', 'Selecciona todas las que apliquen. ¿Qué hallazgos sugieren una lesión endo-periodontal combinada?', '["bolsa periodontal profunda","movilidad dental","respuesta pulpar alterada o ausente","ausencia total de inflamación gingival","dentina coronaria sana en toda su extensión"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Fíjate en qué signos afectan a la vez al periodonto y a la pulpa.', 30, 3, '{"lesion-endo-periodontal","diagnostico"}'),
  ('endodoncia', 3, 'match', 'Empareja cada complicación de la endodoncia con su definición.', NULL, NULL, NULL, '[{"left":"Sobreinstrumentación","right":"La preparación rebasa el foramen apical"},{"left":"Sobreobturación","right":"El material de obturación se extiende más allá del ápice"},{"left":"Subobturación","right":"El material de obturación queda corto del ápice"},{"left":"Filtración coronaria","right":"Paso de microorganismos por un sellado coronal deficiente"}]', NULL, NULL, NULL, NULL, 35, 3, '{"errores-de-procedimiento","complicaciones"}'),
  ('endodoncia', 3, 'order', 'Ordena los pasos de un retratamiento endodóntico convencional.', NULL, NULL, NULL, NULL, '[{"text":"Acceso y localización del material de obturación","position":1},{"text":"Remoción de la gutapercha con calor, solventes o ultrasonido","position":2},{"text":"Nueva instrumentación y limpieza del sistema de conductos","position":3},{"text":"Irrigación y desinfección final","position":4},{"text":"Obturación con la técnica elegida","position":5}]', NULL, NULL, NULL, 35, 3, '{"retratamiento","procedimiento"}'),
  ('endodoncia', 3, 'case', '¿Cuál es el diagnóstico clínico más probable?', NULL, NULL, NULL, NULL, NULL, 'en-case-retratamiento', 'Paciente de 47 años acude por dolor a la masticación en el diente 36 y sensación de presión. Refiere una endodoncia realizada hace tres años. A la exploración presenta percusión dolorosa y sensibilidad a la palpación apical, sin edema extraoral. La radiografía muestra una obturación radicular corta del ápice, una radiolucidez periapical asociada que no aparecía en la radiografía del año anterior y un cono que se extiende ligeramente más allá del foramen.', 'Relaciona la endodoncia previa, el dolor y la lesión nueva en la radiografía.', 35, 3, '{"caso-clinico","retratamiento","diagnostico"}'),
  ('endodoncia', 3, 'case', '¿Cuál es el manejo más adecuado para este paciente?', NULL, NULL, NULL, NULL, NULL, 'en-case-retratamiento', 'Paciente de 47 años acude por dolor a la masticación en el diente 36 y sensación de presión. Refiere una endodoncia realizada hace tres años. A la exploración presenta percusión dolorosa y sensibilidad a la palpación apical, sin edema extraoral. La radiografía muestra una obturación radicular corta del ápice, una radiolucidez periapical asociada que no aparecía en la radiografía del año anterior y un cono que se extiende ligeramente más allá del foramen.', 'La lesión nueva y la obturación deficiente hacen conveniente rehacer el conducto, no extraer.', 35, 3, '{"caso-clinico","plan-de-tratamiento"}'),
  ('endodoncia', 3, 'case', 'Durante el retratamiento se confirma que el cono sobrepasa el ápice (sobreobturación). ¿Qué conducta es la correcta?', NULL, NULL, NULL, NULL, NULL, 'en-case-retratamiento', 'Paciente de 47 años acude por dolor a la masticación en el diente 36 y sensación de presión. Refiere una endodoncia realizada hace tres años. A la exploración presenta percusión dolorosa y sensibilidad a la palpación apical, sin edema extraoral. La radiografía muestra una obturación radicular corta del ápice, una radiolucidez periapical asociada que no aparecía en la radiografía del año anterior y un cono que se extiende ligeramente más allá del foramen.', 'El material que ya irrita el ápice no debe quedar ahí ni repetirse.', 35, 3, '{"caso-clinico","sobreobturacion","manejo"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('operatoria-dental', 1, 'mcq', '¿Cuál es el principal componente orgánico de la dentina?', '["Colágeno tipo I","Queratina","Elastina","Colágeno tipo IV"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en la proteína estructural que predomina en los tejidos mineralizados del diente.', 10, 1, '{"estructura-dentina","composicion","nivel-1"}'),
  ('operatoria-dental', 1, 'mcq', '¿Qué células se encuentran en la periferia de la pulpa y son responsables de la formación de la dentina?', '["Odontoblastos","Ameloblastos","Cementoblastos","Osteoblastos"]', 0, NULL, NULL, NULL, NULL, NULL, 'Son las células que viven ''pegadas'' a la dentina, en la parte externa de la pulpa.', 10, 1, '{"pulpa","odontoblastos","histologia","nivel-1"}'),
  ('operatoria-dental', 1, 'mcq', '¿Cuál es el principal componente inorgánico del esmalte dental?', '["Hidroxiapatita","Calcita","Carbonato de calcio","Sulfato de calcio"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es el mineral de calcio y fosfato que forma la fase dura de los tejidos calcificados.', 10, 1, '{"esmalte","composicion","nivel-1"}'),
  ('operatoria-dental', 1, 'mcq', 'El índice de placa de O''Leary (IP) expresa:', '["El porcentaje de superficies dentales con placa bacteriana revelada","La profundidad de las bolsas periodontales","El grado de movilidad dental","El nivel de sangrado al sondaje"]', 0, NULL, NULL, NULL, NULL, NULL, 'Se calcula dividiendo las superficies teñidas entre el total de superficies examinadas.', 10, 1, '{"indice-de-placa","diagnostico","prevencion","nivel-1"}'),
  ('operatoria-dental', 1, 'mcq', 'La pulpa dental está constituida por:', '["Tejido conectivo laxo con vasos y nervios","Tejido epitelial estratificado","Tejido óseo esponjoso","Cartílago hialino"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es el ''nervio del diente'', el tejido blando que se inflama en las pulpitis.', 10, 1, '{"pulpa","histologia","nivel-1"}'),
  ('operatoria-dental', 1, 'mcq', '¿Cuál es la función principal del cemento radicular?', '["Permitir la inserción de las fibras del ligamento periodontal","Formar el esmalte de la corona","Cubrir la cámara pulpar","Proteger la dentina de la caries"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es el tejido que ''sujeta'' el diente a su ligamento alrededor de la raíz.', 10, 1, '{"cemento","periodonto","nivel-1"}'),
  ('operatoria-dental', 1, 'mcq', 'La línea que marca la unión entre el esmalte y la dentina se denomina:', '["Unión amelodentinaria","Unión cementodentinaria","Línea cervical","Línea de crecimiento"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es la frontera entre los dos tejidos duros principales de la corona.', 10, 1, '{"esmalte","dentina","anatomia","nivel-1"}'),
  ('operatoria-dental', 1, 'true_false', 'La dentina es menos radiopaca que el esmalte en una radiografía periapical.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en cuál de los dos tejidos aparece ''más blanco'' en la imagen.', 10, 1, '{"dentina","esmalte","radiografia","nivel-1"}'),
  ('operatoria-dental', 1, 'true_false', 'La pulpa dental carece de inervación y, por tanto, no responde a los estímulos.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, 'Si la pulpa no respondiera, no existiría la sensibilidad al frío o al calor.', 10, 1, '{"pulpa","inervacion","diagnostico","nivel-1"}'),
  ('operatoria-dental', 1, 'fill_blank', 'La unidad estructural básica del esmalte se denomina ____.', '["prisma del esmalte","túbulo dentinario","capa odontoblástica","unidad cementaria"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es la ''columna'' vertical que forma la estructura del esmalte.', 10, 1, '{"esmalte","prisma","nivel-1"}'),
  ('operatoria-dental', 1, 'fill_blank', 'Las células que sintetizan la matriz del esmalte durante la formación del diente se denominan ____.', '["ameloblastos","odontoblastos","cementoblastos","fibroblastos"]', 0, NULL, NULL, NULL, NULL, NULL, 'Su nombre empieza igual que la palabra inglesa para esmalte: enamel.', 10, 1, '{"esmalte","ameloblastos","histologia","nivel-1"}'),
  ('operatoria-dental', 1, 'fill_blank', 'La porción del diente visible en la cavidad bucal, expuesta por encima de la encía, se denomina ____.', '["corona clínica","corona anatómica","cuello dental","raíz clínica"]', 0, NULL, NULL, NULL, NULL, NULL, 'Su tamaño depende del nivel de la encía, no del esmalte.', 10, 1, '{"anatomia","corona-clinica","nivel-1"}'),
  ('operatoria-dental', 1, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles son funciones de la saliva que protegen contra la caries dental?', '["Acción de limpieza que arrastra restos alimentarios","Capacidad amortiguadora que neutraliza los ácidos","Aporta iones calcio y fosfato para la remineralización","Disminuye el flujo salival para secar las superficies","Aumenta la acidez del medio bucal"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Elimina las opciones que describen un efecto negativo o ''secante''.', 10, 1, '{"saliva","prevencion","caries","nivel-1"}'),
  ('operatoria-dental', 1, 'match', 'Empareja cada método de prevención con su mecanismo de acción.', NULL, NULL, NULL, '[{"left":"Sellantes de fosas y fisuras","right":"Barrera física que ocluye las fosas oclusales"},{"left":"Cepillado dental","right":"Remoción mecánica del biofilm de las superficies"},{"left":"Control de azúcares en la dieta","right":"Disminuye el sustrato disponible para los microorganismos"},{"left":"Control odontológico periódico","right":"Detección temprana de lesiones incipientes"}]', NULL, NULL, NULL, 'Relaciona cada método con la fase del proceso carioso que interrumpe.', 15, 1, '{"prevencion","sellantes","higiene","nivel-1"}'),
  ('operatoria-dental', 1, 'match', 'Empareja cada tejido del diente con su localización.', NULL, NULL, NULL, '[{"left":"Esmalte","right":"Recubre la corona del diente por fuera"},{"left":"Dentina","right":"Forma la mayor parte del cuerpo de la corona y la raíz"},{"left":"Pulpa","right":"Ocupa la cámara pulpar y los conductos radiculares"},{"left":"Cemento","right":"Recubre la superficie radicular"}]', NULL, NULL, NULL, 'Piensa en la disposición ''de afuera hacia adentro'' del diente.', 15, 1, '{"anatomia","tejidos-dentarios","nivel-1"}'),
  ('operatoria-dental', 1, 'order', 'Ordena los pasos para la colocación del aislamiento absoluto con dique de goma.', NULL, NULL, NULL, NULL, '[{"text":"Perforar el dique de goma en la posición del diente o dientes a aislar","position":1},{"text":"Seleccionar el clamp adecuado y colocarlo en el diente","position":2},{"text":"Deslizar el dique sobre el clamp y asentarlo en el diente","position":3},{"text":"Colocar el arco y ajustar la tensión del dique","position":4},{"text":"Invertir los bordes del dique en el cuello de los dientes con la sonda","position":5}]', NULL, NULL, 'Piensa en qué debe estar ''listo'' antes de que el dique toque el diente.', 15, 1, '{"aislamiento-absoluto","dique-de-goma","operatoria","nivel-1"}'),
  ('operatoria-dental', 2, 'mcq', 'Los composites se clasifican principalmente según:', '["El tamaño de las partículas de relleno inorgánico","El color de la matriz resinosa","El tipo de iniciador de la polimerización","La cantidad de matriz orgánica"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es el criterio que explica por qué existen composites ''nanohíbridos'' o ''microrelleno''.', 20, 2, '{"composite","clasificacion","materiales","nivel-2"}'),
  ('operatoria-dental', 2, 'mcq', 'En un sistema adhesivo, la función principal del primer es:', '["Penetrar en la dentina desmineralizada y estabilizar la red de colágeno","Grabar el esmalte para crear microretenciones","Fotopolimerizar la capa de adhesivo","Pulir la superficie cavitaria"]', 0, NULL, NULL, NULL, NULL, NULL, 'Su función es ''preparar el camino'' hacia la dentina recién grabada.', 20, 2, '{"adhesivo","primer","dentina","nivel-2"}'),
  ('operatoria-dental', 2, 'mcq', 'El principio de forma de resistencia en una preparación cavitaria busca:', '["Evitar la fractura del diente y de la restauración bajo las fuerzas masticatorias","Facilitar la limpieza del campo operatorio","Mejorar la estética del margen","Reducir el tiempo de trabajo clínico"]', 0, NULL, NULL, NULL, NULL, NULL, 'Se relaciona con ''resistir'' la masticación, no con la estética.', 20, 2, '{"preparacion-cavitaria","forma-de-resistencia","operatoria","nivel-2"}'),
  ('operatoria-dental', 2, 'mcq', 'En las restauraciones adhesivas con resina compuesta, la retención se obtiene principalmente por:', '["Unión micromecánica a través del sistema adhesivo","Fricción mecánica de paredes paralelas","Espigas metálicas de retención","Forma de cola de milano"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en el mecanismo que permite ''pegar'' el composite sin fresar retenciones.', 20, 2, '{"adhesion","retencion","composite","nivel-2"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('operatoria-dental', 2, 'mcq', 'En una lesión proximal en un diente anterior, el acceso que mejor preserva la estética facial es:', '["Lingual","Facial","Incisal","Cervical"]', 0, NULL, NULL, NULL, NULL, NULL, 'Imagina por qué lado del diente el paciente ''no vería'' la restauración al sonreír.', 20, 2, '{"lesion-proximal","acceso","estetica","operatoria","nivel-2"}'),
  ('operatoria-dental', 2, 'mcq', 'Los composites fluidos (flow) se caracterizan por:', '["Menor viscosidad y menor contenido de relleno que los convencionales","Mayor contenido de relleno inorgánico que los convencionales","No requerir fotopolimerización","Estar indicados únicamente en dientes anteriores"]', 0, NULL, NULL, NULL, NULL, NULL, 'Su nombre (''flow'') ya describe su comportamiento al fluir.', 20, 2, '{"composite","fluido","materiales","nivel-2"}'),
  ('operatoria-dental', 2, 'mcq', 'La matriz orgánica de una resina compuesta está constituida por:', '["Monómeros de resina como el Bis-GMA","Partículas de vidrio de bario","Agentes de acoplamiento silano","Pigmentos inorgánicos"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es la parte que ''se cura'' con la luz y forma el polímero.', 20, 2, '{"composite","matriz-organica","materiales","nivel-2"}'),
  ('operatoria-dental', 2, 'mcq', 'Las lámparas de fotopolimerización modernas emiten luz visible de longitud de onda de aproximadamente:', '["450-480 nm (luz azul)","620-700 nm (luz roja)","200-300 nm (luz ultravioleta)","520-550 nm (luz verde)"]', 0, NULL, NULL, NULL, NULL, NULL, 'Si alguna vez viste una lámpara de fotocurado, recuerda el color de su luz.', 20, 2, '{"fotopolimerizacion","lampara","materiales","nivel-2"}'),
  ('operatoria-dental', 2, 'true_false', 'El biselado del margen de esmalte en una preparación adhesiva mejora el sellado de la restauración.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, 'Relaciona ''más superficie de esmalte'' con ''mejor adhesión''.', 20, 2, '{"biselado","margen","adhesion","nivel-2"}'),
  ('operatoria-dental', 2, 'true_false', 'La adhesión del composite al esmalte es más predecible y duradera que la adhesión a la dentina.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en cuál de los dos tejidos es más ''seco y uniforme'' para adherirse.', 20, 2, '{"adhesion","esmalte","dentina","nivel-2"}'),
  ('operatoria-dental', 2, 'true_false', 'La matriz de acero, al ser transparente, permite la fotopolimerización del composite a través de ella.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, 'Piensa en el color y la transparencia de cada tipo de matriz.', 20, 2, '{"matriz","composite","aislamiento","nivel-2"}'),
  ('operatoria-dental', 2, 'fill_blank', 'El ____ es el agente de acoplamiento que une las partículas de relleno inorgánico a la matriz orgánica del composite.', '["silano","fotoiniciador","primer","pigmento"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es la molécula ''puente'' entre el vidrio y la resina.', 20, 2, '{"silano","composite","materiales","nivel-2"}'),
  ('operatoria-dental', 2, 'fill_blank', 'En una restauración proximal posterior, la ____ de madera separa los dientes y comprime la matriz para restablecer el punto de contacto.', '["cuña","matriz","arco","clamp"]', 0, NULL, NULL, NULL, NULL, NULL, 'Se introduce en el espacio entre los dientes, por debajo de la matriz.', 20, 2, '{"restauracion-proximal","matriz","contacto-proximal","operatoria","nivel-2"}'),
  ('operatoria-dental', 2, 'multi_select', 'Selecciona todas las que apliquen. ¿Qué funciones cumple el relleno inorgánico en un composite?', '["Incrementar la resistencia mecánica","Reducir el coeficiente de expansión térmica","Mejorar la resistencia al desgaste","Volver el material más elástico y gomoso","Eliminar la necesidad de fotopolimerización"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Fíjate en qué propiedades ''mejoran'' con un material más duro y relleno.', 20, 2, '{"composite","relleno","materiales","nivel-2"}'),
  ('operatoria-dental', 2, 'multi_select', 'Selecciona todas las que apliquen. ¿Qué condiciones favorecen una correcta adhesión a la dentina?', '["Superficie libre de restos de caries","Ausencia de contaminación por saliva","Humedad controlada, sin sobresecar el tejido","Presencia de una capa gruesa de barro dentinario","Dentina completamente deshidratada"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'La dentina ideal para adherirse es ''limpia, aislada y ligeramente húmeda''.', 20, 2, '{"adhesion","dentina","tecnicas-adhesivas","nivel-2"}'),
  ('operatoria-dental', 2, 'match', 'Empareja cada instrumento con su función clínica en operatoria dental.', NULL, NULL, NULL, '[{"left":"Dique de goma","right":"Mantiene el campo seco y libre de saliva"},{"left":"Fresa de fisura","right":"Configura y alisa las paredes de la preparación"},{"left":"Explorador","right":"Detecta caries y evalúa los márgenes"},{"left":"Gomas de pulido","right":"Alisan y dan brillo a la superficie restaurada"}]', NULL, NULL, NULL, 'Relaciona cada instrumento con la etapa del procedimiento en que se usa.', 25, 2, '{"instrumental","operatoria","nivel-2"}'),
  ('operatoria-dental', 2, 'order', 'Ordena los pasos del acabado y pulido de una restauración de composite.', NULL, NULL, NULL, NULL, '[{"text":"Eliminar los excesos groseros con una fresa de grano grueso","position":1},{"text":"Refinar los márgenes con fresas o discos de grano fino","position":2},{"text":"Pulir la superficie con gomas de silicona o discos flexibles","position":3},{"text":"Aplicar pasta de pulir con cepillo y dar el brillo final","position":4}]', NULL, NULL, 'La regla es ''de grueso a fino''.', 25, 2, '{"pulido","acabado","composite","nivel-2"}'),
  ('operatoria-dental', 3, 'mcq', 'En un paciente joven se observan opacidades blanco-amarillentas asimétricas en primeros molares e incisivos permanentes, sin historia de traumatismo. El diagnóstico más probable es:', '["Hipomineralización de incisivos y molares (HMI)","Fluorosis dental","Caries incipiente","Amelogénesis imperfecta"]', 0, NULL, NULL, NULL, NULL, NULL, 'Fíjate en qué dientes se afectan: primeros molares e incisivos permanentes.', 30, 3, '{"manchas-blancas","diagnostico-diferencial","hipomineralizacion","nivel-3"}'),
  ('operatoria-dental', 3, 'mcq', 'Durante la preparación cavitaria se identifica esmalte sin soporte dentinario. La conducta correcta es:', '["Eliminarlo, porque es frágil y se fracturará bajo las cargas","Conservarlo siempre para no ampliar la preparación","Recubrirlo con base y restaurar encima","Grabarlo durante más tiempo para reforzarlo"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en lo que ocurrirá con ese ''techo de esmalte'' al masticar.', 30, 3, '{"esmalte-sin-soporte","preparacion-cavitaria","nivel-3"}'),
  ('operatoria-dental', 3, 'mcq', 'La microfiltración en el margen de una restauración de composite se manifiesta clínicamente por:', '["Pigmentación o sombra en el margen, con sensibilidad ocasional","Superficie brillante y lisa","Cambio de color del cuerpo sin defecto marginal","Presencia de cálculo supragingival"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es el ''escape'' entre el diente y la restauración, visible como línea oscura en el margen.', 30, 3, '{"microfiltracion","margen","restauracion","nivel-3"}'),
  ('operatoria-dental', 3, 'mcq', 'Para la detección de caries proximales y recurrentes bajo restauraciones, la técnica radiográfica más indicada es:', '["Radiografía interproximal (bitewing)","Radiografía oclusal","Radiografía panorámica","Tomografía de haz cónico de toda la arcada"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es la radiografía que ''abre'' el contacto entre las coronas de los molares.', 30, 3, '{"radiografia","diagnostico","caries-proximal","nivel-3"}'),
  ('operatoria-dental', 3, 'mcq', 'En una abfracción sintomática en la cara vestibular de un premolar, sin caries y con buena higiene, el tratamiento inicial más apropiado es:', '["Restauración adhesiva que cubra y selle la lesión","Extracción del diente afectado","Ajuste oclusal exclusivo, sin restaurar","Corona de recubrimiento total de inmediato"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en el objetivo de ''cubrir'' la dentina expuesta que causa la sensibilidad.', 30, 3, '{"abfraccion","lesion-cervical","tratamiento","nivel-3"}'),
  ('operatoria-dental', 3, 'true_false', 'En los dientes jóvenes, los cuernos pulpares altos aumentan el riesgo de exposición pulpar durante la preparación cavitaria.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, 'Relaciona ''diente joven'' con ''cámara pulpar grande''.', 30, 3, '{"pulpa","preparacion-cavitaria","paciente-joven","nivel-3"}'),
  ('operatoria-dental', 3, 'true_false', 'La caries recurrente bajo una restauración siempre produce dolor espontáneo antes de ser detectable.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, 'Piensa si el dolor es un signo temprano o tardío de la caries.', 30, 3, '{"caries-recurrente","diagnostico","nivel-3"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('operatoria-dental', 3, 'fill_blank', 'La caries que se localiza en el cemento y la dentina radicular expuesta se denomina caries ____.', '["radicular","coronal","de fosas y fisuras","interproximal"]', 0, NULL, NULL, NULL, NULL, NULL, 'Lleva el nombre de la parte del diente que afecta.', 30, 3, '{"caries-radicular","raiz","nivel-3"}'),
  ('operatoria-dental', 3, 'fill_blank', 'Una restauración con un defecto marginal pequeño y localizado, sin caries subyacente, puede ____ en lugar de reemplazarse por completo.', '["repararse","extraerse","descementarse","pulirse"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es el enfoque ''mínimamente invasivo'' frente a un defecto puntual.', 30, 3, '{"reparacion","reemplazo","restauracion","nivel-3"}'),
  ('operatoria-dental', 3, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles son causas de sensibilidad postoperatoria en restauraciones adhesivas?', '["Contaminación de la dentina con saliva durante la adhesión","Fotopolimerización insuficiente del composite","Sobregrabado de la dentina con desecación posterior","Uso de anestesia local","Eliminación de todos los márgenes de esmalte"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Busca las opciones que describen fallas en la técnica adhesiva.', 30, 3, '{"sensibilidad-postoperatoria","adhesion","complicaciones","nivel-3"}'),
  ('operatoria-dental', 3, 'multi_select', 'Selecciona todas las que apliquen. ¿Qué hallazgos indican una restauración fallida que requiere intervención?', '["Defecto marginal donde el explorador se atrapa","Fractura de un segmento de la restauración","Caries recurrente visible en el margen","Ligero cambio de color sin defecto ni filtración","Superficie oclusal pulida e intacta"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Descarta las opciones que describen un diente ''sano'' o solo un cambio cosmético.', 30, 3, '{"restauracion-fallida","margen","evaluacion","nivel-3"}'),
  ('operatoria-dental', 3, 'multi_select', 'Selecciona todas las que apliquen. ¿Qué factores aumentan el riesgo de caries radicular?', '["Recesión gingival con exposición de la raíz","Xerostomía o disminución del flujo salival","Higiene deficiente en las superficies radiculares","Esmalte grueso en la corona","Uso diario de hilo dental"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Piensa en qué condiciones dejan la raíz ''desprotegida''.', 30, 3, '{"caries-radicular","factores-de-riesgo","nivel-3"}'),
  ('operatoria-dental', 3, 'match', 'Empareja cada lesión cervical no cariosa con su mecanismo de producción.', NULL, NULL, NULL, '[{"left":"Abfracción","right":"Lesión en cuña en el límite amelocementario, asociada a fuerzas de flexión oclusal"},{"left":"Abrasión","right":"Desgaste por fricción externa, frecuente por cepillado horizontal intenso"},{"left":"Erosión","right":"Pérdida química de estructura por ácidos, con superficie lisa y cóncava"},{"left":"Atrición","right":"Desgaste por contacto diente contra diente, habitual en bruxismo"}]', NULL, NULL, NULL, 'Piensa en el origen de cada lesión: fuerza, fricción, ácido o contacto dentario.', 35, 3, '{"lesiones-cervicales","abfraccion","abrasion","erosion","atricion","nivel-3"}'),
  ('operatoria-dental', 3, 'order', 'Ordena los pasos del manejo de una lesión cervical no cariosa con hipersensibilidad.', NULL, NULL, NULL, NULL, '[{"text":"Identificar y controlar el factor etiológico (hábitos, dieta u oclusión)","position":1},{"text":"Evaluar la profundidad de la lesión y la sensibilidad del diente","position":2},{"text":"Restaurar la lesión con técnica adhesiva si persiste la hipersensibilidad","position":3},{"text":"Realizar el control periódico y reforzar las medidas preventivas","position":4}]', NULL, NULL, 'Lo primero nunca es restaurar: primero hay que detener la causa.', 35, 3, '{"lesion-cervical","manejo","tratamiento","nivel-3"}'),
  ('operatoria-dental', 3, 'case', 'Según el cuadro, el diagnóstico más probable es:', NULL, NULL, NULL, NULL, NULL, 'op-case-caries-recurrente', 'Paciente de 42 años acude por molestia ocasional al masticar en el primer molar inferior derecho. El diente presenta una restauración de composite oclusal colocada hace 5 años. En el margen distal se observa pigmentación marrón y el explorador se atrapa levemente; la radiografía interproximal muestra una radiolucidez limitada a dentina superficial bajo el margen distal de la restauración.', 'Relaciona los tres hallazgos: margen pigmentado, explorador atrapado y radiolucidez.', 35, 3, '{"caries-recurrente","caso-clinico","diagnostico","nivel-3"}'),
  ('operatoria-dental', 3, 'case', 'Dado que la lesión es pequeña y limitada a dentina superficial, el tratamiento más conservador es:', NULL, NULL, NULL, NULL, NULL, 'op-case-caries-recurrente', 'Paciente de 42 años acude por molestia ocasional al masticar en el primer molar inferior derecho. El diente presenta una restauración de composite oclusal colocada hace 5 años. En el margen distal se observa pigmentación marrón y el explorador se atrapa levemente; la radiografía interproximal muestra una radiolucidez limitada a dentina superficial bajo el margen distal de la restauración.', 'Elige la opción que elimina la caries y restaura, sin tratamientos radicales.', 35, 3, '{"caries-recurrente","caso-clinico","tratamiento","nivel-3"}'),
  ('operatoria-dental', 3, 'case', '¿Qué medida contribuye a prevenir nuevas lesiones recurrentes en este paciente?', NULL, NULL, NULL, NULL, NULL, 'op-case-caries-recurrente', 'Paciente de 42 años acude por molestia ocasional al masticar en el primer molar inferior derecho. El diente presenta una restauración de composite oclusal colocada hace 5 años. En el margen distal se observa pigmentación marrón y el explorador se atrapa levemente; la radiografía interproximal muestra una radiolucidez limitada a dentina superficial bajo el margen distal de la restauración.', 'Piensa en qué hábito reduce el biofilm en el margen de la restauración.', 35, 3, '{"caries-recurrente","caso-clinico","prevencion","nivel-3"}'),
  ('ortodoncia', 1, 'mcq', 'En el sistema de notación dental de la FDI (Federación Dental Internacional), el primer dígito indica el cuadrante y el segundo la posición del diente. ¿Qué código identifica al primer molar superior derecho permanente?', '["16","26","46","36"]', 0, NULL, NULL, NULL, NULL, NULL, 'El primer dígito identifica el cuadrante: 1 = superior derecho.', 10, 1, '{"nomenclatura dental","sistema FDI"}'),
  ('ortodoncia', 1, 'mcq', '¿Cuál de los siguientes dientes temporales es, por lo general, el primero en erupcionar en la cavidad bucal del niño?', '["Incisivo central inferior","Incisivo central superior","Primer molar superior","Canino inferior"]', 0, NULL, NULL, NULL, NULL, NULL, 'Los primeros dientes suelen aparecer en la arcada inferior y en la zona anterior.', 10, 1, '{"erupción","dentición decidua"}'),
  ('ortodoncia', 1, 'mcq', 'Respecto a la morfología, ¿cuál es una característica distintiva de la corona de los dientes temporales frente a sus sucesores permanentes?', '["Es más ancha en sentido mesiodistal en relación con su altura","Presenta mayor grosor de esmalte","Es más estrecha mesiodistalmente que el cuello","Tiene una coloración amarillenta marcada"]', 0, NULL, NULL, NULL, NULL, NULL, 'Compara la proporción ancho-altura de la corona temporal con la permanente.', 10, 1, '{"morfología dental","dentición decidua"}'),
  ('ortodoncia', 1, 'mcq', 'En un bracket convencional, ¿qué parte es la que se adhiere directamente a la superficie del esmalte dental?', '["La base","El slot (ranura)","Los alerones (aletas)","El gancho"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en la cara del bracket que queda en contacto con el diente.', 10, 1, '{"aparatología fija","brackets"}'),
  ('ortodoncia', 1, 'mcq', '¿Cuántos dientes conforman la dentición permanente completa en un adulto, incluyendo los terceros molares?', '["32","28","24","36"]', 0, NULL, NULL, NULL, NULL, NULL, 'Suma incisivos, caninos, premolares y molares de ambas arcadas.', 10, 1, '{"dentición permanente","anatomía dental"}'),
  ('ortodoncia', 1, 'mcq', '¿Cuántas raíces presenta normalmente el primer molar superior permanente?', '["Tres","Una","Dos","Cinco"]', 0, NULL, NULL, NULL, NULL, NULL, 'Recuerda la clásica trirradicularidad del primer molar superior.', 10, 1, '{"morfología dental","primer molar superior"}'),
  ('ortodoncia', 1, 'true_false', 'El esmalte de los dientes temporales es más delgado que el de los dientes permanentes.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 10, 1, '{"dentición decidua","esmalte"}'),
  ('ortodoncia', 1, 'true_false', 'Los dientes permanentes presentan, en general, coronas más pequeñas que los dientes temporales que reemplazan.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, NULL, 10, 1, '{"dentición permanente","tamaño dental"}'),
  ('ortodoncia', 1, 'true_false', 'La caries en los dientes temporales no tiene ningún efecto sobre los dientes permanentes.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, NULL, 10, 1, '{"dentición decidua","caries"}'),
  ('ortodoncia', 1, 'fill_blank', 'Los dientes posteriores cuya función principal es triturar los alimentos son los ____.', '["molares y premolares","incisivos","caninos","temporales"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 10, 1, '{"anatomía dental","función dentaria"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('ortodoncia', 1, 'fill_blank', 'Los terceros molares, conocidos también como ____, son los últimos dientes en erupcionar en la dentición permanente.', '["muelas del juicio","caninos","premolares","incisivos"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 10, 1, '{"terceros molares","erupción"}'),
  ('ortodoncia', 1, 'fill_blank', 'El tejido que recubre la raíz del diente y en el que se insertan las fibras del ligamento periodontal se denomina ____.', '["cemento","esmalte","pulpa","dentina"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 10, 1, '{"anatomía dental","cemento"}'),
  ('ortodoncia', 1, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles de los siguientes son hábitos orales que pueden influir en el desarrollo de la oclusión y que el ortodoncista evalúa en el diagnóstico?', '["Succión digital","Respiración bucal","Deglución atípica","Cepillado dental correcto","Uso de hilo dental"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, NULL, 10, 1, '{"hábitos","diagnóstico"}'),
  ('ortodoncia', 1, 'match', 'Empareja cada superficie dental con su descripción.', NULL, NULL, NULL, '[{"left":"Cara vestibular","right":"Superficie orientada hacia el labio o la mejilla"},{"left":"Cara lingual o palatina","right":"Superficie orientada hacia la lengua o el paladar"},{"left":"Cara mesial","right":"Superficie más próxima a la línea media"},{"left":"Cara distal","right":"Superficie más alejada de la línea media"}]', NULL, NULL, NULL, NULL, 15, 1, '{"nomenclatura dental","superficies"}'),
  ('ortodoncia', 1, 'match', 'Empareja cada diente permanente con su edad típica de erupción.', NULL, NULL, NULL, '[{"left":"Primer molar permanente","right":"Erupciona alrededor de los 6 años"},{"left":"Canino superior permanente","right":"Erupciona alrededor de los 11 a 12 años"},{"left":"Incisivo lateral superior","right":"Erupciona alrededor de los 7 a 8 años"},{"left":"Segundo molar permanente","right":"Erupciona alrededor de los 12 años"}]', NULL, NULL, NULL, NULL, 15, 1, '{"erupción","cronología"}'),
  ('ortodoncia', 1, 'order', 'Ordena de forma cronológica las etapas de la dentición.', NULL, NULL, NULL, NULL, '[{"text":"Erupción de los dientes temporales","position":1},{"text":"Dentición decidua completa","position":2},{"text":"Inicio de la dentición mixta","position":3},{"text":"Dentición permanente","position":4}]', NULL, NULL, NULL, 15, 1, '{"dentición","cronología"}'),
  ('ortodoncia', 2, 'mcq', '¿Cuál de los siguientes alambres se caracteriza por ser superelástico y por ello se emplea con frecuencia en las fases iniciales de nivelación y alineación?', '["Níquel-titanio (NiTi)","Acero inoxidable","Titanio-molibdeno (TMA)","Cromo-cobalto"]', 0, NULL, NULL, NULL, NULL, NULL, 'Busca el alambre con memoria de forma y baja rigidez.', 20, 2, '{"arcos","níquel-titanio","biomecánica"}'),
  ('ortodoncia', 2, 'mcq', '¿Cómo se denominan los elásticos que se colocan entre el arco superior y el arco inferior para modificar la relación entre ambas arcadas?', '["Elásticos intermaxilares","Ligaduras metálicas","Cadenetas de cierre","Separadores elásticos"]', 0, NULL, NULL, NULL, NULL, NULL, 'El nombre indica que van entre maxilares.', 20, 2, '{"elásticos","biomecánica"}'),
  ('ortodoncia', 2, 'mcq', 'En un bracket convencional, ¿cuál es la función principal de la ligadura?', '["Mantener el arco dentro del slot","Generar fuerzas de intrusión","Separar los dientes","Cerrar espacios"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es lo que amarra el arco al bracket.', 20, 2, '{"aparatología fija","ligaduras"}'),
  ('ortodoncia', 2, 'mcq', 'Durante el movimiento dental ortodóncico, ¿qué células son las principales responsables de la resorción ósea en el lado de presión del ligamento periodontal?', '["Osteoclastos","Osteoblastos","Fibroblastos","Odontoblastos"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 20, 2, '{"biología del movimiento","periodonto"}'),
  ('ortodoncia', 2, 'mcq', '¿Cómo se denomina el movimiento dentario en el que la corona se inclina y el ápice permanece casi en su posición original?', '["Inclinación (tipping)","Movimiento de cuerpo (traslación)","Rotación","Intrusión"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en un diente que se dobla por la corona.', 20, 2, '{"tipos de movimiento","biomecánica"}'),
  ('ortodoncia', 2, 'mcq', '¿Cuál es la función de los separadores (elásticos o metálicos) en ortodoncia?', '["Crear espacio interproximal para la colocación de bandas","Cerrar espacios de extracción","Enderezar las raíces","Servir de ligadura del arco"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 20, 2, '{"bandas","separadores"}'),
  ('ortodoncia', 2, 'mcq', '¿Qué material se utiliza habitualmente para adherir los brackets al esmalte dental?', '["Resina compuesta","Amalgama de plata","Óxido de zinc y eugenol","Silicona de impresión"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 20, 2, '{"adhesión","aparatología fija"}'),
  ('ortodoncia', 2, 'true_false', 'El desgaste interproximal (stripping o desgaste proximal) es un recurso válido para ganar espacio en apiñamientos dentales leves o moderados.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 20, 2, '{"espacio","desgaste interproximal"}'),
  ('ortodoncia', 2, 'true_false', 'Las cadenetas elásticas se utilizan habitualmente para cerrar espacios entre los dientes.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 20, 2, '{"cadenetas","cierre de espacios"}'),
  ('ortodoncia', 2, 'fill_blank', 'El movimiento en el que la corona y el ápice del diente se desplazan en la misma dirección y en la misma cantidad se denomina movimiento de ____.', '["cuerpo o traslación","inclinación","rotación","extrusión"]', 0, NULL, NULL, NULL, NULL, NULL, 'El diente se desliza completo, sin inclinarse.', 20, 2, '{"tipos de movimiento","biomecánica"}'),
  ('ortodoncia', 2, 'fill_blank', 'El dispositivo que conserva el espacio dejado por un diente temporal hasta la erupción de su sucesor permanente se denomina ____.', '["mantenedor de espacio","retenedor fijo","arco de cierre","arco de intrusión"]', 0, NULL, NULL, NULL, NULL, NULL, 'Su nombre indica que mantiene el espacio.', 20, 2, '{"dentición mixta","mantenedores de espacio"}'),
  ('ortodoncia', 2, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles de los siguientes son objetivos fundamentales del tratamiento de ortodoncia?', '["Lograr una oclusión funcional y estable","Mejorar la estética dental y facial","Obtener resultados estables a largo plazo","Eliminar la necesidad de higiene dental","Aumentar el tamaño de los dientes"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, NULL, 20, 2, '{"objetivos del tratamiento","plan de tratamiento"}'),
  ('ortodoncia', 2, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles de los siguientes son componentes de la aparatología fija convencional?', '["Brackets","Arco de ortodoncia","Ligaduras","Férula de contención","Aparato removible de acrílico"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, NULL, 20, 2, '{"aparatología fija","componentes"}'),
  ('ortodoncia', 2, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles de las siguientes son recomendaciones habituales para un paciente con ortodoncia fija durante el tratamiento?', '["Mantener una higiene rigurosa con cepillos interdentales","Evitar alimentos muy duros o pegajosos","Asistir puntualmente a los controles periódicos","Suprimir por completo el cepillado para no dañar los brackets","Usar exclusivamente colutorios en lugar del cepillado"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, NULL, 20, 2, '{"higiene","cuidados del paciente"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('ortodoncia', 2, 'match', 'Empareja cada componente de un aparato removible con su función.', NULL, NULL, NULL, '[{"left":"Tornillo de expansión","right":"Activa la expansión del aparato removible"},{"left":"Resortes","right":"Producen movimientos puntuales, por ejemplo de un canino"},{"left":"Arcos de retención (Adams)","right":"Sujetan el aparato a los dientes"},{"left":"Placa acrílica","right":"Base del aparato removible"}]', NULL, NULL, NULL, NULL, 25, 2, '{"aparatología removible","componentes"}'),
  ('ortodoncia', 2, 'match', 'Empareja cada tipo de bracket con su característica principal.', NULL, NULL, NULL, '[{"left":"Bracket metálico","right":"El más utilizado por su resistencia y costo accesible"},{"left":"Bracket cerámico","right":"Más estético, aunque más frágil"},{"left":"Bracket autoligable","right":"Retiene el arco sin necesidad de ligaduras"},{"left":"Bracket lingual","right":"Se coloca en la cara lingual del diente"}]', NULL, NULL, NULL, NULL, 25, 2, '{"brackets","tipos"}'),
  ('ortodoncia', 2, 'order', 'Ordena la secuencia habitual de arcos durante un tratamiento de ortodoncia fija.', NULL, NULL, NULL, NULL, '[{"text":"Arco de níquel-titanio de calibre fino","position":1},{"text":"Arco de níquel-titanio de mayor calibre","position":2},{"text":"Arco de acero inoxidable de trabajo","position":3},{"text":"Arco de finalización y acabado","position":4}]', NULL, NULL, NULL, 25, 2, '{"secuencia de arcos","nivelación"}'),
  ('ortodoncia', 3, 'mcq', 'Un paciente adulto de 45 años, con periodontitis tratada y estabilizada, solicita tratamiento ortodóncico para cerrar espacios. ¿Cuál es la conducta más adecuada antes y durante el tratamiento?', '["Evaluar el riesgo periodontal y coordinar con periodoncia con un estricto control de placa","Iniciar el tratamiento con fuerzas pesadas para acortar los plazos","Omitir la higiene especial porque el periodonto ya está sano","Evitar por completo la evaluación periodontal"]', 0, NULL, NULL, NULL, NULL, NULL, 'La salud del periodonto es la base para mover dientes con seguridad.', 30, 3, '{"ortodoncia en adultos","periodoncia"}'),
  ('ortodoncia', 3, 'mcq', 'En un niño se detecta un diente supernumerario (mesiodens) entre los incisivos centrales superiores. ¿Cuál es la complicación más frecuente asociada a su presencia?', '["Retención o alteración de la erupción del incisivo permanente","Sobreerupción del incisivo vecino","Aumento del tamaño de la corona","Fractura espontánea del diente permanente"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"dientes supernumerarios","erupción"}'),
  ('ortodoncia', 3, 'mcq', '¿En cuál de las siguientes condiciones es más frecuente que el ortodoncista solicite la valoración y el manejo conjunto con fonoaudiología?', '["Disfunciones orofaciales y deglución atípica","Caries extensa no tratada","Bruxismo nocturno aislado","Enfermedad periodontal activa"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"fonoaudiología","deglución atípica","interdisciplinario"}'),
  ('ortodoncia', 3, 'mcq', 'Ante una asimetría mandibular notable en un paciente en crecimiento, ¿qué estudio es indispensable para descartar alteraciones del cóndilo o de la articulación temporomandibular?', '["Tomografía computarizada de haz cónico (CBCT)","Fotografía intraoral","Examen con sonda periodontal","Prueba de vitalidad pulpar"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"asimetría","ATM","imagenología"}'),
  ('ortodoncia', 3, 'mcq', 'En términos generales, ¿qué tipo de fuerza se considera la más adecuada para producir un movimiento dental eficiente y con menor daño tisular?', '["Fuerzas ligeras y continuas","Fuerzas pesadas e intermitentes","Fuerzas pesadas aplicadas de forma continua","Fuerzas intensas de corta duración"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"biomecánica","fuerzas óptimas"}'),
  ('ortodoncia', 3, 'mcq', '¿Cuál es el fundamento de la corticotomía para acelerar el movimiento dentario?', '["Provoca un fenómeno de aceleración del recambio óseo regional (RAP)","Aumenta directamente el tamaño de los dientes","Elimina la necesidad de aparatología","Endurece el hueso para lograr mayor anclaje"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"corticotomía","movimiento acelerado"}'),
  ('ortodoncia', 3, 'mcq', 'Un molar temporal permanece en infraoclusión (sumergido) en comparación con sus vecinos. ¿Cuál es la causa más probable?', '["Anquilosis del diente temporal","Caries extensa del diente","Sobreerupción del diente vecino","Traumatismo reciente"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"anquilosis","dentición mixta"}'),
  ('ortodoncia', 3, 'true_false', 'Los dientes que han recibido tratamiento de conducto (endodoncia) están contraindicados de forma absoluta para el movimiento ortodóncico.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"endodoncia","movimiento dental"}'),
  ('ortodoncia', 3, 'true_false', 'La colaboración del paciente (cumplimiento del uso de elásticos y de la higiene) no influye en el resultado final del tratamiento de ortodoncia.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"cumplimiento","elásticos"}'),
  ('ortodoncia', 3, 'fill_blank', 'Excluyendo los terceros molares, el diente que con mayor frecuencia presenta agenesia (ausencia congénita) es el ____.', '["segundo premolar inferior","incisivo central superior","primer molar","canino inferior"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"agenesia","hipodoncia"}'),
  ('ortodoncia', 3, 'fill_blank', 'La medida más importante para prevenir la desmineralización del esmalte (manchas blancas) durante un tratamiento de ortodoncia fija es el control de ____.', '["placa bacteriana","temperatura bucal","pH salival","posición del bracket"]', 0, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, '{"desmineralización","higiene","prevención"}'),
  ('ortodoncia', 3, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles de las siguientes son consideraciones importantes al planificar la ortodoncia en un paciente adulto?', '["Evaluar la salud periodontal y la presencia de enfermedad activa","Considerar que el crecimiento óseo ya se completó","Coordinar con otras especialidades cuando sea necesario","Aplicar fuerzas pesadas continuas para acelerar el tratamiento","Ignorar las expectativas estéticas del paciente"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, NULL, 30, 3, '{"ortodoncia en adultos","plan de tratamiento"}'),
  ('ortodoncia', 3, 'multi_select', 'Selecciona todas las que apliquen. ¿En cuáles de las siguientes situaciones es recomendable la evaluación o el manejo interdisciplinario durante el tratamiento ortodóncico?', '["Paciente con enfermedad periodontal activa","Paciente con disfunción temporomandibular (ATM)","Paciente con asimetrías esqueléticas severas","Paciente con caries pequeñas y controladas","Paciente asintomático sin patologías asociadas"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, NULL, 30, 3, '{"interdisciplinario","ATM","periodoncia"}'),
  ('ortodoncia', 3, 'order', 'Ordena los pasos del manejo inicial de un paciente que acude por un alambre que se salió y le molesta.', NULL, NULL, NULL, NULL, '[{"text":"Identificar la zona que causa la molestia","position":1},{"text":"Cubrir el extremo del alambre con cera ortodóncica","position":2},{"text":"Acudir al ortodoncista para el ajuste definitivo","position":3}]', NULL, NULL, NULL, 35, 3, '{"urgencias","manejo clínico"}'),
  ('ortodoncia', 3, 'case', 'Con base en el caso, ¿cuál es el diagnóstico más probable?', NULL, NULL, NULL, NULL, NULL, 'or-case-erupcion-ectopica', 'Paciente femenina de 9 años acude por molestias al masticar del lado derecho. En el examen clínico y radiográfico se observa el primer molar superior derecho en erupción ectópica, con reabsorción de la raíz distal del segundo molar temporal adyacente y leve inflamación gingival en la zona.', NULL, 35, 3, '{"erupción ectópica","diagnóstico"}'),
  ('ortodoncia', 3, 'case', '¿Cuál es la conducta ortodóncica inicial más adecuada en este caso?', NULL, NULL, NULL, NULL, NULL, 'or-case-erupcion-ectopica', 'Paciente femenina de 9 años acude por molestias al masticar del lado derecho. En el examen clínico y radiográfico se observa el primer molar superior derecho en erupción ectópica, con reabsorción de la raíz distal del segundo molar temporal adyacente y leve inflamación gingival en la zona.', NULL, 35, 3, '{"erupción ectópica","manejo interceptivo"}'),
  ('ortodoncia', 3, 'case', 'Si el cuadro no se corrige a tiempo, ¿qué consecuencia es la más probable?', NULL, NULL, NULL, NULL, NULL, 'or-case-erupcion-ectopica', 'Paciente femenina de 9 años acude por molestias al masticar del lado derecho. En el examen clínico y radiográfico se observa el primer molar superior derecho en erupción ectópica, con reabsorción de la raíz distal del segundo molar temporal adyacente y leve inflamación gingival en la zona.', NULL, 35, 3, '{"erupción ectópica","complicaciones"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('periodoncia', 1, 'mcq', 'La película adquirida o cutícula que se forma sobre la superficie dental tiene su origen principal en:', '["Proteínas de la saliva","Células del epitelio descamado","Bacterias del surco gingival","Azúcares de la dieta"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en qué sustancia baña constantemente los dientes desde el inicio.', 10, 1, '{"película adquirida","placa dental"}'),
  ('periodoncia', 1, 'mcq', 'Las primeras bacterias que colonizan la superficie dental limpia pertenecen principalmente a:', '["Cocos grampositivos (estreptococos)","Bacilos gramnegativos anaerobios","Espiroquetas","Bacterias pigmentadas negras"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué grupo bacteriano actúa como colonizador pionero sobre la superficie limpia?', 10, 1, '{"placa dental","colonización bacteriana"}'),
  ('periodoncia', 1, 'mcq', 'El cálculo dental contribuye a la enfermedad periodontal principalmente porque:', '["Su superficie rugosa retiene placa y dificulta la higiene","Es tóxico de forma directa para las células epiteliales","Altera el pH salival en pocas horas","Es de origen genético y no requiere placa"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en el papel del cálculo como superficie de retención de nueva placa.', 10, 1, '{"cálculo dental","etiología"}'),
  ('periodoncia', 1, 'mcq', 'El índice gingival de Löe-Silness evalúa:', '["El grado de inflamación gingival","La profundidad de las bolsas periodontales","La pérdida ósea radiográfica","La movilidad dental"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es un índice que observa la encía y sus cambios, no la bolsa.', 10, 1, '{"índices periodontales","índice gingival"}'),
  ('periodoncia', 1, 'mcq', 'La estructura que marca el límite entre la encía y la mucosa alveolar se denomina:', '["Línea (unión) mucogingival","Surco gingival","Línea de la sonrisa","Papila interdental"]', 0, NULL, NULL, NULL, NULL, NULL, 'Busca el límite entre dos tejidos de color y movilidad distintos.', 10, 1, '{"anatomía","unión mucogingival"}'),
  ('periodoncia', 1, 'mcq', 'La halitosis de origen bucal se asocia principalmente con:', '["Compuestos sulfurados volátiles producidos por bacterias","Deficiencia de vitamina C","Infecciones de las vías respiratorias superiores","Consumo elevado de azúcares"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué producen las bacterias al degradar proteínas y que huele mal?', 10, 1, '{"halitosis","placa dental"}'),
  ('periodoncia', 1, 'mcq', 'La placa bacteriana dental es una biopelícula (biofilm) que:', '["Se adhiere firmemente a las superficies y resiste los enjuagues","Se elimina por completo con un solo cepillado","Es inofensiva mientras no sea visible a simple vista","Es exclusivamente de origen alimentario, sin bacterias"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Por qué los enjuagues solos no eliminan la placa?', 10, 1, '{"placa dental","biopelícula"}'),
  ('periodoncia', 1, 'mcq', 'La zona dentaria más propensa a la acumulación de placa y al desarrollo de enfermedad periodontal es:', '["La zona interproximal (espacios interdentales)","La fosa oclusal","El borde incisal","La cara labial media"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es la zona que el cepillo no alcanza fácilmente.', 10, 1, '{"placa dental","higiene interdental"}'),
  ('periodoncia', 2, 'mcq', 'En la evaluación periodontal completa, la profundidad de sondaje de cada diente se registra en:', '["6 sitios: 3 por vestibular y 3 por lingual/palatino","4 sitios: mesial, distal, vestibular y lingual","3 sitios: vestibular, lingual y oclusal","2 sitios: mesial y distal"]', 0, NULL, NULL, NULL, NULL, NULL, 'Cuenta cuántas caras se exploran por cada lado del diente.', 20, 2, '{"evaluación periodontal","sondaje"}'),
  ('periodoncia', 2, 'mcq', 'Según la clasificación de Miller, la movilidad dental de grado 2 corresponde a un desplazamiento horizontal de:', '["Entre 1 y 2 mm","Menos de 1 mm","Más de 2 mm o en sentido vertical","Cualquier movimiento solo con percusión"]', 0, NULL, NULL, NULL, NULL, NULL, 'Recuerda los tres grados: menor de 1, entre 1 y 2, y mayor de 2.', 20, 2, '{"movilidad dental","evaluación"}'),
  ('periodoncia', 2, 'mcq', 'Una ventaja de la instrumentación ultrasónica frente a la manual es:', '["Reducir el tiempo de trabajo en superficies con cálculo abundante","Eliminar la necesidad de alisar la raíz","No requerir irrigación durante su uso","No generar aerosoles durante el procedimiento"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en la eficiencia sobre depósitos grandes.', 20, 2, '{"instrumentación ultrasónica","raspado"}'),
  ('periodoncia', 2, 'mcq', 'Al afilar una cureta periodontal, el objetivo principal es:', '["Restaurar el filo conservando la angulación de la hoja","Aumentar el ángulo de la hoja para volverla más agresiva","Reducir la longitud de la hoja","Enderezar la curva de la hoja"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué se pierde con el uso y se recupera al afilar?', 20, 2, '{"afilado","instrumentos periodontales"}'),
  ('periodoncia', 2, 'mcq', 'El objetivo principal de la terapia de mantenimiento periodontal es:', '["Prevenir la recurrencia y la progresión de la enfermedad","Reemplazar todas las restauraciones defectuosas","Sustituir el cepillado por enjuagues antisépticos","Realizar cirugía en cada cita de control"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué fase del tratamiento evita que la enfermedad vuelva?', 20, 2, '{"mantenimiento periodontal","terapia de soporte"}'),
  ('periodoncia', 2, 'mcq', 'El colgajo periodontal de Widman modificado se caracteriza por:', '["Conservar las papilas interdentales","Eliminar toda la encía queratinizada","Realizar incisiones horizontales en el hueso","Desplazar el margen gingival hacia apical"]', 0, NULL, NULL, NULL, NULL, NULL, 'Piensa en una cirugía que busca acceso y conservación del tejido.', 20, 2, '{"cirugía periodontal","colgajo de Widman"}'),
  ('periodoncia', 2, 'mcq', 'El alargamiento coronario quirúrgico se indica principalmente para:', '["Exponer mayor corona clínica respetando el espacio biológico","Eliminar cálculo subgingival profundo","Regenerar hueso perdido","Aumentar la encía queratinizada"]', 0, NULL, NULL, NULL, NULL, NULL, 'Se indica antes de restaurar dientes con poca corona clínica.', 20, 2, '{"alargamiento coronario","cirugía"}'),
  ('periodoncia', 3, 'mcq', 'El agrandamiento gingival inducido por medicamentos se asocia clásicamente con el uso de:', '["Fenitoína, ciclosporina y nifedipino","Penicilina, amoxicilina y metronidazol","Paracetamol, ibuprofeno y naproxeno","Insulina, metformina y glibenclamida"]', 0, NULL, NULL, NULL, NULL, NULL, 'Son fármacos de grupos muy distintos: un antiepiléptico, un inmunosupresor y un bloqueador de canales de calcio.', 30, 3, '{"agrandamiento gingival","medicamentos"}'),
  ('periodoncia', 3, 'mcq', 'En un diente con fístula en la encía insertada y periodonto clínicamente sano en el resto de la boca, la causa más probable es:', '["Una lesión de origen endodóntico","Una periodontitis generalizada","Una lesión de furca aislada","Un trauma oclusal crónico"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué origen explica un drenaje localizado sin bolsas en el resto de la boca?', 30, 3, '{"endo-perio","diagnóstico"}'),
  ('periodoncia', 3, 'mcq', 'Durante la reevaluación tras la fase inicial, un sitio que persiste con bolsa de 6 mm y sangrado al sondaje indica:', '["Que la terapia debe continuarse en ese sitio","El éxito definitivo del tratamiento","Inflamación fisiológica normal","Sobretratamiento del sitio"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué te dice que la inflamación sigue activa en el sitio?', 30, 3, '{"reevaluación","bolsa residual"}'),
  ('periodoncia', 3, 'mcq', 'La osteoporosis se ha asociado con:', '["Mayor pérdida ósea e inserción en pacientes con periodontitis","Menor formación de cálculo dental","Aumento de la encía queratinizada","Menor respuesta inflamatoria gingival"]', 0, NULL, NULL, NULL, NULL, NULL, 'Relaciona una enfermedad de baja masa ósea con el soporte del diente.', 30, 3, '{"osteoporosis","factores sistémicos"}'),
  ('periodoncia', 3, 'mcq', 'El injerto óseo en cirugía periodontal se indica principalmente en defectos:', '["Intraóseos con paredes óseas que contengan el material","Supraóseos sin paredes óseas","Solo en recesiones gingivales aisladas","Sitios con movilidad grado 3 no controlada"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué tipo de defecto ofrece paredes para sostener el material injertado?', 30, 3, '{"injertos óseos","regeneración"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('periodoncia', 1, 'true_false', 'La pigmentación melánica de la encía en personas de piel oscura debe tratarse siempre como una lesión patológica.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, '¿Es la pigmentación oscura algo normal en ciertos pacientes?', 10, 1, '{"encía sana","pigmentación"}'),
  ('periodoncia', 1, 'true_false', 'El cálculo supragingival suele tener un color blanco amarillento, mientras que el subgingival tiende a presentar una coloración más oscura.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, 'Compara dónde se forma cada tipo y qué lo tiñe.', 10, 1, '{"cálculo dental","cálculo subgingival"}'),
  ('periodoncia', 2, 'true_false', 'El raspado ultrasónico debe reemplazar siempre al raspado manual en el alisado radicular.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, '¿Puede el ultrasonido lograr siempre el acabado fino de la raíz?', 20, 2, '{"instrumentación ultrasónica","raspado"}'),
  ('periodoncia', 2, 'true_false', 'El colgajo periodontal de espesor total (mucoperióstico) incluye el periostio junto con la encía.', '["Verdadero","Falso"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué capa profunda acompaña al colgajo en esta técnica?', 20, 2, '{"cirugía periodontal","colgajo"}'),
  ('periodoncia', 2, 'true_false', 'La cirugía periodontal de colgajo debe indicarse antes de completar la fase higiénica del tratamiento.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, '¿En qué momento del tratamiento se decide la cirugía?', 20, 2, '{"cirugía periodontal","secuencia de tratamiento"}'),
  ('periodoncia', 3, 'true_false', 'La férula periodontal está indicada para estabilizar dientes con movilidad grado 3 en un paciente con enfermedad activa sin tratar.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, '¿Una férula resuelve la inflamación subyacente?', 30, 3, '{"ferulización","movilidad"}'),
  ('periodoncia', 3, 'true_false', 'En la periimplantitis, la cirugía de descontaminación de la superficie del implante es el tratamiento de elección de primera línea en todos los casos.', '["Verdadero","Falso"]', 1, NULL, NULL, NULL, NULL, NULL, '¿Siempre se necesita cirugía para tratar la periimplantitis?', 30, 3, '{"periimplantitis","manejo"}'),
  ('periodoncia', 1, 'fill_blank', 'Para visualizar la placa bacteriana en la consulta se emplean comprimidos reveladores que contienen ____.', '["eritrosina","melanina","peróxido","queratina"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es un colorante rojo utilizado como revelador de placa.', 10, 1, '{"índices de placa","revelador de placa"}'),
  ('periodoncia', 1, 'fill_blank', 'El cálculo dental se origina cuando la placa bacteriana se ____ sobre la superficie dentaria.', '["mineraliza","desorganiza","queratiniza","fermenta"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué proceso transforma la placa blanda en cálculo duro?', 10, 1, '{"cálculo dental","placa dental"}'),
  ('periodoncia', 2, 'fill_blank', 'El índice de placa de Silness-Löe puntúa la cantidad de placa en una escala de 0 a ____.', '["3","2","4","5"]', 0, NULL, NULL, NULL, NULL, NULL, 'Es la misma escala 0-3 que usa el índice gingival.', 20, 2, '{"índices de placa","Silness-Löe"}'),
  ('periodoncia', 2, 'fill_blank', 'En la instrumentación ultrasónica, la punta activa del instrumento vibra a alta ____ para fragmentar la placa y el cálculo.', '["frecuencia","presión","temperatura","densidad"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué propiedad de la onda permite el efecto mecánico del ultrasonido?', 20, 2, '{"instrumentación ultrasónica","ultrasonido"}'),
  ('periodoncia', 2, 'fill_blank', 'Para explorar la movilidad dental se aplica una fuerza con los mangos de dos instrumentos en sentido ____.', '["vestibulolingual","mesiodistal","vertical","apical"]', 0, NULL, NULL, NULL, NULL, NULL, '¿En qué dirección se mueve normalmente un diente al presionarlo?', 20, 2, '{"movilidad dental","evaluación"}'),
  ('periodoncia', 3, 'fill_blank', 'En la paciente gestante, los procedimientos periodontales electivos se prefieren durante el ____ trimestre.', '["segundo","primer","tercer","cuarto"]', 0, NULL, NULL, NULL, NULL, NULL, 'Ni muy temprano ni muy tarde en la gestación.', 30, 3, '{"embarazo","factores sistémicos"}'),
  ('periodoncia', 3, 'fill_blank', 'En la terapia de mantenimiento periodontal, el intervalo entre citas se establece según el ____ individual de recidiva del paciente.', '["riesgo","color","sexo","turno"]', 0, NULL, NULL, NULL, NULL, NULL, '¿Qué evaluación guía la frecuencia de los controles?', 30, 3, '{"mantenimiento periodontal","riesgo de recidiva"}'),
  ('periodoncia', 1, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles son características clínicas de la encía sana?', '["Color rosado coral","Contorno festoneado","Sangrado espontáneo","Puntilleo presente","Recesión generalizada"]', NULL, '{0,1,3}', NULL, NULL, NULL, NULL, 'Descarta todo lo que sugiera inflamación o pérdida de tejido.', 10, 1, '{"encía sana","anatomía"}'),
  ('periodoncia', 1, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles son signos clínicos de inflamación gingival?', '["Enrojecimiento (eritema)","Pérdida del puntilleo","Color rosado coral","Edema o tumefacción","Ausencia total de sangrado"]', NULL, '{0,1,3}', NULL, NULL, NULL, NULL, 'Busca cambios que reflejen aumento del riego sanguíneo y del líquido en el tejido.', 10, 1, '{"inflamación","signos clínicos"}'),
  ('periodoncia', 2, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles son instrumentos de la instrumentación periodontal manual?', '["Escalador (hoc)","Curetas","Bisturí","Azada (hoe)","Fresa quirúrgica"]', NULL, '{0,1,3}', NULL, NULL, NULL, NULL, 'Piensa en instrumentos de hoja diseñados para raspar, no para cortar o fresar.', 20, 2, '{"instrumentos manuales","instrumentación"}'),
  ('periodoncia', 2, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles son medidas de control mecánico de placa recomendadas al paciente?', '["Cepillado dental","Uso de hilo (seda) dental","Uso de cepillos interdentales","Evitar el cepillado para no lastimar la encía","Reemplazar el cepillado solo por enjuagues"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Selecciona métodos físicos que remuevan la placa de las superficies.', 20, 2, '{"control de placa","higiene"}'),
  ('periodoncia', 3, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles condiciones sistémicas pueden modificar la presentación de la enfermedad periodontal?', '["Embarazo","Osteoporosis","Infección por VIH","Fractura de clavícula","Otitis externa"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Descarta afecciones que no involucran el sistema de soporte dental.', 30, 3, '{"factores sistémicos","modificadores"}'),
  ('periodoncia', 3, 'multi_select', 'Selecciona todas las que apliquen. ¿Cuáles son signos de alarma que obligan a manejar con urgencia al paciente periodontal?', '["Fiebre y malestar general asociados a supuración","Tumefacción fluctuante y dolorosa de inicio súbito","Movilidad marcada de aparición brusca en varios dientes","Pérdida leve de encía queratinizada sin inflamación","Cálculo supragingival visible sin síntomas"]', NULL, '{0,1,2}', NULL, NULL, NULL, NULL, 'Piensa en cuadros agudos con compromiso local o general.', 30, 3, '{"urgencias","signos de alarma"}');
insert into public.questions (specialty_slug, level, question_type, question, options, correct_index, correct_indexes, pairs, order_items, case_id, case_text, hint, points, difficulty, tags)
  values
  ('periodoncia', 1, 'match', 'Relaciona cada parte de la encía con su descripción.', NULL, NULL, NULL, '[{"left":"Encía marginal","right":"Borde libre de encía que rodea el cuello del diente"},{"left":"Encía insertada","right":"Encía firme y queratinizada adherida al hueso y a la raíz"},{"left":"Papila interdental","right":"Encía que ocupa el espacio entre dos dientes adyacentes"},{"left":"Mucosa alveolar","right":"Mucosa móvil, no queratinizada, que se continúa con el vestíbulo"}]', NULL, NULL, NULL, NULL, 15, 1, '{"anatomía","encía"}'),
  ('periodoncia', 2, 'match', 'Relaciona cada instrumento periodontal manual con su función.', NULL, NULL, NULL, '[{"left":"Escalador (hoc)","right":"Eliminar cálculo supragingival en zonas accesibles"},{"left":"Azada (hoe)","right":"Alisar superficies radiculares planas y amplias"},{"left":"Cincel","right":"Eliminar cálculo en zonas interdentales estrechas"},{"left":"Cureta universal","right":"Raspado supragingival y subgingival con filo redondeado"}]', NULL, NULL, NULL, NULL, 25, 2, '{"instrumentos manuales","función"}'),
  ('periodoncia', 3, 'match', 'Relaciona cada hallazgo clínico con su significado.', NULL, NULL, NULL, '[{"left":"Supuración al sondaje","right":"Actividad inflamatoria aguda en la bolsa"},{"left":"Movilidad grado 3","right":"Desplazamiento mayor a 2 mm o en sentido vertical"},{"left":"Recesión gingival","right":"Desplazamiento apical del margen gingival"},{"left":"Bolsa periodontal","right":"Surco profundizado con pérdida de inserción"}]', NULL, NULL, NULL, NULL, 35, 3, '{"signos clínicos","evaluación"}'),
  ('periodoncia', 3, 'match', 'Relaciona cada tipo de lesión endoperiodontal con su origen.', NULL, NULL, NULL, '[{"left":"Lesión primariamente endodóntica","right":"Infección pulpar que drena a través del periodonto"},{"left":"Lesión primariamente periodontal","right":"Enfermedad periodontal que produce afectación pulpar"},{"left":"Lesión endoperiodontal verdadera","right":"Coexistencia de enfermedad pulpar y periodontal que confluyen"},{"left":"Lesión endodóntica con compromiso periodontal","right":"Lesión pulpar que se extiende a la furca o al margen gingival"}]', NULL, NULL, NULL, NULL, 35, 3, '{"endo-perio","clasificación"}'),
  ('periodoncia', 1, 'order', 'Ordena las etapas de la formación de la placa dental sobre una superficie limpia.', NULL, NULL, NULL, NULL, '[{"text":"Formación de la película adquirida","position":1},{"text":"Adhesión de las primeras bacterias a la superficie","position":2},{"text":"Crecimiento y agregación de microcolonias","position":3},{"text":"Maduración y aumento de la biopelícula","position":4}]', NULL, NULL, NULL, 15, 1, '{"placa dental","formación de placa"}'),
  ('periodoncia', 2, 'order', 'Ordena la secuencia de la instrumentación ultrasónica del cálculo.', NULL, NULL, NULL, NULL, '[{"text":"Seleccionar la punta (inserto) adecuada","position":1},{"text":"Ajustar la potencia y la irrigación","position":2},{"text":"Colocar la punta activa en contacto con el cálculo","position":3},{"text":"Realizar movimientos continuos y suaves sobre la superficie","position":4}]', NULL, NULL, NULL, 25, 2, '{"instrumentación ultrasónica","secuencia"}'),
  ('periodoncia', 3, 'order', 'Ordena el manejo inicial de una lesión endoperiodontal combinada.', NULL, NULL, NULL, NULL, '[{"text":"Evaluación clínica y radiográfica del diente y el periodonto","position":1},{"text":"Tratamiento de conducto (endodoncia) del diente afectado","position":2},{"text":"Reevaluación de la respuesta del tejido periodontal","position":3},{"text":"Terapia periodontal del sitio si la lesión persiste","position":4}]', NULL, NULL, NULL, 35, 3, '{"endo-perio","plan de tratamiento"}'),
  ('periodoncia', 3, 'case', '¿Cuál es el diagnóstico más probable del 36?', NULL, NULL, NULL, NULL, NULL, 'pe-case-1', 'Mujer de 42 años acude por dolor pulsátil e inflamación en la zona del primer molar inferior izquierdo (36) desde hace 2 días. Refiere periodontitis diagnosticada años atrás, pero lleva tiempo sin controles. Al examen presenta tumefacción ovalada y fluctuante en la encía vestibular del 36, bolsa de 9 mm con supuración al sondaje y leve movilidad; el resto de la boca muestra bolsas de 5 a 6 mm con sangrado generalizado. No hay fiebre ni compromiso sistémico.', 'Relaciona la bolsa profunda y la supuración con la inflamación del periodonto.', 35, 3, '{"absceso periodontal","urgencias","diagnóstico"}'),
  ('periodoncia', 3, 'case', '¿Cuál es la conducta inicial más apropiada en este momento?', NULL, NULL, NULL, NULL, NULL, 'pe-case-1', 'Mujer de 42 años acude por dolor pulsátil e inflamación en la zona del primer molar inferior izquierdo (36) desde hace 2 días. Refiere periodontitis diagnosticada años atrás, pero lleva tiempo sin controles. Al examen presenta tumefacción ovalada y fluctuante en la encía vestibular del 36, bolsa de 9 mm con supuración al sondaje y leve movilidad; el resto de la boca muestra bolsas de 5 a 6 mm con sangrado generalizado. No hay fiebre ni compromiso sistémico.', 'Lo prioritario es liberar la presión del material purulento.', 35, 3, '{"absceso periodontal","urgencias","manejo"}'),
  ('periodoncia', 3, 'case', 'Una vez resuelta la urgencia, ¿cuál es el siguiente paso en el manejo integral de la paciente?', NULL, NULL, NULL, NULL, NULL, 'pe-case-1', 'Mujer de 42 años acude por dolor pulsátil e inflamación en la zona del primer molar inferior izquierdo (36) desde hace 2 días. Refiere periodontitis diagnosticada años atrás, pero lleva tiempo sin controles. Al examen presenta tumefacción ovalada y fluctuante en la encía vestibular del 36, bolsa de 9 mm con supuración al sondaje y leve movilidad; el resto de la boca muestra bolsas de 5 a 6 mm con sangrado generalizado. No hay fiebre ni compromiso sistémico.', 'Piensa en la secuencia general: fase inicial, reevaluación y después corrección.', 35, 3, '{"plan de tratamiento","fase inicial","mantenimiento"}');
